/*
  Seed khóa học Tiếng Nhật N5 từ docs/BAI_HOC_N5_BAI_01.md đến BAI_HOC_N5_BAI_25.md.

  Kết quả: 1 course, 25 course_section và 156 course_content.
  Chạy database_language_center_mysql.sql và seed_language_center_mysql.sql trước file này.
  Có thể chạy lại file mà không tạo dữ liệu trùng.
*/

SET NAMES utf8mb4;
USE LanguageCenterDB;

START TRANSACTION;

SET @n5_lesson_level_id = NULL;
SELECT lv.id INTO @n5_lesson_level_id
FROM level lv
JOIN language lg ON lg.id = lv.language_id
WHERE lg.language_code = 'JA' AND lv.level_code = 'N5'
LIMIT 1;

    level_id, course_code, course_name, slug, short_description, description,
    target_audience, prerequisites, learning_outcomes, syllabus_summary,
    tuition_fee, total_sessions, duration_hours, status, publication_status,
    published_at, is_featured, created_at, updated_at
)
SELECT
    @n5_lesson_level_id,
    'JA-N5-LESSONS',
    'Tiếng Nhật N5 - 25 bài học tổng hợp',
    'tieng-nhat-n5-25-bai-hoc-tong-hop',
    'Khóa N5 gồm 25 bài tích hợp từ vựng, ngữ pháp, đọc, nghe và hội thoại.',
    'Nội dung được tổng hợp từ bộ bài học Markdown N5, kèm ví dụ, luyện tập và đáp án.',
    'Người mới bắt đầu hoặc học viên đang ôn JLPT N5.',
    'Nên biết Hiragana và Katakana cơ bản.',
    'Sử dụng được từ vựng, ngữ pháp và mẫu giao tiếp trọng tâm trình độ N5.',
    '25 bài từ giới thiệu bản thân đến mẫu câu điều kiện たら và nhượng bộ ても.',
    0, 25, 50, 'ACTIVE', 'PUBLISHED', NOW(), TRUE, NOW(), NOW()
WHERE @n5_lesson_level_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM course WHERE course_code = 'JA-N5-LESSONS');

SET @n5_lesson_course_id = NULL;
SELECT id INTO @n5_lesson_course_id
FROM course
WHERE course_code = 'JA-N5-LESSONS'
LIMIT 1;

DROP TEMPORARY TABLE IF EXISTS n5_lesson_section_seed;
CREATE TEMPORARY TABLE n5_lesson_section_seed (
    lesson_number INT NOT NULL PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    description TEXT NULL
);


SELECT @n5_lesson_course_id, seed.title, seed.description, seed.lesson_number
FROM n5_lesson_section_seed seed
WHERE @n5_lesson_course_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1 FROM course_section existing_section
      WHERE existing_section.course_id = @n5_lesson_course_id
        AND existing_section.display_order = seed.lesson_number
  );

DROP TEMPORARY TABLE IF EXISTS n5_lesson_content_seed;
CREATE TEMPORARY TABLE n5_lesson_content_seed (
    lesson_number INT NOT NULL,
    item_order INT NOT NULL,
    title VARCHAR(255) NOT NULL,
    summary TEXT NULL,
    content_html LONGTEXT NULL,
    content_type VARCHAR(30) NOT NULL,
    PRIMARY KEY (lesson_number, item_order)
);


    section_id, title, summary, content_html, content_type,
    display_order, is_preview, publication_status
)
SELECT
    section.id,
    seed.title,
    seed.summary,
    seed.content_html,
    seed.content_type,
    seed.item_order,
    TRUE,
    'PUBLISHED'
FROM n5_lesson_content_seed seed
JOIN course_section section
  ON section.course_id = @n5_lesson_course_id
 AND section.display_order = seed.lesson_number
WHERE NOT EXISTS (
    SELECT 1 FROM course_content existing_content
    WHERE existing_content.section_id = section.id
      AND existing_content.display_order = seed.item_order
);

DROP TEMPORARY TABLE n5_lesson_content_seed;
DROP TEMPORARY TABLE n5_lesson_section_seed;

COMMIT;

SELECT
    course.id,
    course.course_code,
    COUNT(DISTINCT section.id) AS section_count,
    COUNT(content.id) AS content_count
FROM course
LEFT JOIN course_section section ON section.course_id = course.id
LEFT JOIN course_content content ON content.section_id = section.id
WHERE course.course_code = 'JA-N5-LESSONS'
GROUP BY course.id, course.course_code;
