INSERT INTO course_section (course_id, title, description, display_order)
INSERT INTO n5_lesson_content_seed
    (lesson_number, item_order, title, summary, content_html, content_type) VALUES
(1, 1, 'Thông tin bài học', 'Trình độ: N5 - nhập môn', '<div class="n5-lesson-content"><p>• Trình độ: N5 - nhập môn</p><p>• Chủ đề: Chào hỏi và giới thiệu bản thân</p><p>• Thời lượng gợi ý: 90 phút</p><p>• Kỹ năng: Từ vựng, ngữ pháp, đọc hiểu, nghe hiểu và hội thoại</p></div>', 'LESSON'),
(1, 2, 'Mục tiêu Can-do', 'Sau bài học, học viên có thể:', '<div class="n5-lesson-content"><p>Sau bài học, học viên có thể:</p><p>• Chào hỏi khi gặp một người lần đầu.</p><p>• Nói tên, quốc tịch, nghề nghiệp và nơi làm việc của mình.</p><p>• Hỏi và xác nhận thông tin cơ bản của người khác.</p><p>• Nói hai người có cùng một đặc điểm bằng trợ từ <code>も</code>.</p></div>', 'LESSON'),
(1, 3, 'Khởi động', 'Quan sát hai người lần đầu gặp nhau và trả lời:', '<div class="n5-lesson-content"><p>Quan sát hai người lần đầu gặp nhau và trả lời:</p><p>1. Họ nên nói câu gì để bắt đầu cuộc trò chuyện?</p><p>2. Bạn thường giới thiệu những thông tin nào về mình?</p><p>3. Trong lần đầu gặp mặt, thông tin nào không nên hỏi quá trực tiếp?</p><p>Cụm từ mở đầu:</p><p>• はじめまして。- Rất vui được gặp bạn.</p><p>• よろしく おねがいします。- Rất mong được bạn giúp đỡ.</p><p>• こちらこそ よろしく おねがいします。- Chính tôi cũng rất mong được bạn giúp đỡ.</p></div>', 'LESSON'),
(1, 4, 'Từ vựng', 'Lưu ý: trong giao tiếp thực tế, nên gọi đối phương bằng tên kèm ～さん thay vì thường xuyên dùng あなた.', '<div class="n5-lesson-content"><h3>4.1. Con người và cách xưng hô</h3><p>Từ vựng | Cách đọc | Nghĩa</p><p>私 | わたし | tôi</p><p>あの人 | あのひと | người kia</p><p>あの方 | あのかた | vị kia, cách nói lịch sự của <code>あの人</code></p><p>彼 | かれ | anh ấy</p><p>彼女 | かのじょ | cô ấy</p><p>名前 | なまえ | tên</p><p>～さん | - | anh/chị/bạn..., đặt sau tên người</p><p>～ちゃん | - | cách gọi thân mật, thường dùng với trẻ em</p><p>だれ | - | ai</p><p>どなた | - | ai, cách nói lịch sự</p><p>Lưu ý: trong giao tiếp thực tế, nên gọi đối phương bằng tên kèm <code>～さん</code> thay vì thường xuyên dùng <code>あなた</code>.</p><h3>4.2. Nghề nghiệp</h3><p>Từ vựng | Cách đọc | Nghĩa</p><p>仕事 | しごと | công việc</p><p>教師 | きょうし | giáo viên, dùng để nói về nghề nghiệp</p><p>先生 | せんせい | giáo viên, bác sĩ; cách gọi thể hiện sự tôn trọng</p><p>会社員 | かいしゃいん | nhân viên công ty</p><p>銀行員 | ぎんこういん | nhân viên ngân hàng</p><p>学生 | がくせい | học sinh, sinh viên</p><p>医者 | いしゃ | bác sĩ</p><p>エンジニア | - | kỹ sư</p><p>歌手 | かしゅ | ca sĩ</p><p>俳優 | はいゆう | diễn viên</p><h3>4.3. Quốc gia và ngôn ngữ</h3><p>Quốc gia | Quốc tịch | Ngôn ngữ</p><p>ベトナム | ベトナム人 | ベトナム語</p><p>日本 | 日本人 | 日本語</p><p>中国 | 中国人 | 中国語</p><p>韓国 | 韓国人 | 韓国語</p><p>アメリカ | アメリカ人 | 英語</p><p>Quy tắc ghi nhớ:</p><p>• Tên nước + <code>人（じん）</code> = người mang quốc tịch đó.</p><p>• Tên nước + <code>語（ご）</code> = ngôn ngữ của nước đó.</p></div>', 'VOCABULARY'),
(1, 5, 'Ngữ pháp trọng tâm', 'Ý nghĩa: N1 là N2.', '<div class="n5-lesson-content"><h3>5.1. <code>N1 は N2 です</code></h3><p>Ý nghĩa: N1 là N2.</p><p>Cách dùng: giới thiệu hoặc cung cấp thông tin khẳng định về tên, quốc tịch và nghề nghiệp.</p><p>• <code>は</code> đánh dấu chủ đề, trong câu này được đọc là <code>わ</code>.</p><p>• <code>です</code> đặt ở cuối câu để tạo sắc thái lịch sự.</p><p>Ví dụ:</p><p>• 私は ミンです。- Tôi là Minh.</p><p>• リーさんは 中国人です。- Bạn Lee là người Trung Quốc.</p><p>• 田中さんは エンジニアです。- Anh Tanaka là kỹ sư.</p><h3>5.2. <code>N1 の N2</code></h3><p>Ý nghĩa: N2 của N1 hoặc N2 thuộc N1.</p><p>Cách dùng trong bài: nói một người thuộc công ty, trường học hoặc tổ chức nào.</p><p>Ví dụ:</p><p>• ABC会社の 社員です。- Tôi là nhân viên của công ty ABC.</p><p>• さくら大学の 学生です。- Tôi là sinh viên của Đại học Sakura.</p><h3>5.3. <code>N1 は N2 じゃありません</code></h3><p>Ý nghĩa: N1 không phải là N2.</p><p>• <code>じゃありません</code> là dạng phủ định lịch sự thông dụng.</p><p>• <code>ではありません</code> trang trọng hơn và thường gặp trong văn viết hoặc hoàn cảnh nghiêm túc.</p><p>Ví dụ:</p><p>• 私は 日本人じゃありません。- Tôi không phải là người Nhật.</p><p>• マイさんは 医者ではありません。- Chị Mai không phải là bác sĩ.</p><h3>5.4. <code>N1 は N2 ですか</code></h3><p>Ý nghĩa: N1 có phải là N2 không?</p><p>Cách trả lời:</p><p>• <code>はい、そうです。</code> - Vâng, đúng vậy.</p><p>• <code>いいえ、ちがいます。</code> - Không, không phải.</p><p>• <code>いいえ、N2 じゃありません。N3 です。</code> - Không phải N2. Là N3.</p><p>Ví dụ:</p><p>• A: アンさんは 学生ですか。</p><p>B: はい、そうです。</p><p>• A: 山田さんは 会社員ですか。</p><p>B: いいえ、会社員じゃありません。教師です。</p><h3>5.5. <code>N1 も N2 です</code></h3><p>Ý nghĩa: N1 cũng là N2.</p><p>Cách dùng: diễn tả N1 có cùng thông tin với đối tượng đã được nói trước đó.</p><p>Ví dụ:</p><p>• ナムさんは ベトナム人です。ランさんも ベトナム人です。</p><p>Nam là người Việt Nam. Lan cũng là người Việt Nam.</p></div>', 'GRAMMAR'),
(1, 6, 'Mẫu câu giao tiếp', 'A: お名前は？ - Tên của bạn là gì?', '<div class="n5-lesson-content"><h3>Hỏi tên</h3><p>• A: お名前は？ - Tên của bạn là gì?</p><p>• B: リンです。- Tôi là Linh.</p><h3>Hỏi nghề nghiệp</h3><p>• A: お仕事は？ - Công việc của bạn là gì?</p><p>• B: 会社員です。- Tôi là nhân viên công ty.</p><h3>Hỏi một người là ai</h3><p>• A: あの方は どなたですか。- Vị kia là ai vậy?</p><p>• B: 日本語の 先生です。- Đó là giáo viên tiếng Nhật.</p></div>', 'LESSON'),
(1, 7, 'Đọc hiểu', 'Đọc ba hồ sơ sau:', '<div class="n5-lesson-content"><p>Đọc ba hồ sơ sau:</p><blockquote>はじめまして。私は リンです。ベトナム人です。さくら大学の 学生です。</blockquote><blockquote>はじめまして。私は ケンです。日本人です。ABC会社の エンジニアです。</blockquote><blockquote>私は ソヨンです。韓国人です。学生じゃありません。銀行員です。</blockquote><p>Trả lời câu hỏi:</p><p>1. リンさんは どこの 学生ですか。</p><p>2. ケンさんは 会社員ですか。</p><p>3. ソヨンさんは 学生ですか。</p><p>4. Ai là kỹ sư?</p><p>5. Hãy tìm một câu phủ định trong đoạn đọc.</p></div>', 'LESSON'),
(1, 8, 'Nghe hiểu', 'Giáo viên đọc đoạn hội thoại hai lần. Lần một, học viên chọn thông tin đúng. Lần hai, học viên điền từ còn thiếu.', '<div class="n5-lesson-content"><p>Giáo viên đọc đoạn hội thoại hai lần. Lần một, học viên chọn thông tin đúng. Lần hai, học viên điền từ còn thiếu.</p><h3>Câu hỏi trước khi nghe</h3><p>1. Người nữ tên là gì?</p><p>2. Cô ấy mang quốc tịch nào?</p><p>3. Nghề nghiệp của cô ấy là gì?</p><p>4. Người nam có cùng nghề nghiệp với cô ấy không?</p><h3>Kịch bản dành cho giáo viên</h3><p>A: はじめまして。私は たなかです。日本人です。会社員です。</p><p>B: はじめまして。マイです。ベトナム人です。私も 会社員です。</p><p>A: マイさんは ABC会社の 社員ですか。</p><p>B: いいえ、ABC会社の 社員じゃありません。さくら会社の 社員です。</p><p>A: そうですか。よろしく おねがいします。</p><p>B: こちらこそ よろしく おねがいします。</p><h3>Điền từ</h3><p>1. マイさんは __________ 人です。</p><p>2. マイさんも __________ です。</p><p>3. マイさんは ABC会社の 社員 __________。</p><p>4. マイさんは __________ 会社の 社員です。</p></div>', 'LISTENING'),
(1, 9, 'Hội thoại mẫu', 'A: はじめまして。私は ホアです。', '<div class="n5-lesson-content"><p>A: はじめまして。私は ホアです。</p><p>B: はじめまして。私は ゆきです。</p><p>A: ゆきさんは 日本人ですか。</p><p>B: はい、そうです。ホアさんは？</p><p>A: 私は ベトナム人です。会社員です。</p><p>B: 私も 会社員です。</p><p>A: そうですか。よろしく おねがいします。</p><p>B: こちらこそ よろしく おねがいします。</p><h3>Thực hành theo cặp</h3><p>Thay tên, quốc tịch và nghề nghiệp trong hội thoại mẫu bằng thông tin của hai học viên. Mỗi cặp cần sử dụng ít nhất:</p><p>• Một câu khẳng định với <code>です</code>.</p><p>• Một câu hỏi với <code>ですか</code>.</p><p>• Một câu phủ định với <code>じゃありません</code>.</p><p>• Một câu có <code>も</code>.</p></div>', 'LESSON'),
(1, 10, 'Bài tập củng cố', '私（は／の）学生です。', '<div class="n5-lesson-content"><h3>Bài 1. Chọn trợ từ đúng</h3><p>1. 私（は／の）学生です。</p><p>2. ミンさん（は／も）ベトナム人です。ランさんも ベトナム人です。</p><p>3. ABC会社（は／の）社員です。</p><p>4. 田中さん（は／の）先生ですか。</p><h3>Bài 2. Chuyển sang câu phủ định</h3><p>1. 私は 医者です。</p><p>2. リーさんは 日本人です。</p><p>3. マイさんは 学生です。</p><h3>Bài 3. Sắp xếp thành câu đúng</h3><p>1. です／私は／会社員</p><p>2. 日本人／ですか／田中さんは</p><p>3. の／学生です／さくら大学</p><p>4. も／エンジニアです／アンさん</p><h3>Bài 4. Viết giới thiệu bản thân</h3><p>Viết từ bốn đến sáu câu bằng tiếng Nhật, gồm lời chào, tên, quốc tịch, nghề nghiệp hoặc trường/công ty và lời kết thúc.</p></div>', 'EXERCISE'),
(1, 11, 'Đáp án gợi ý', 'さくら大学の 学生です。', '<div class="n5-lesson-content"><h3>Đọc hiểu</h3><p>1. さくら大学の 学生です。</p><p>2. はい、そうです。</p><p>3. いいえ、学生じゃありません。銀行員です。</p><p>4. ケンさんです。</p><p>5. 学生じゃありません。</p><h3>Nghe hiểu</h3><p>1. ベトナム</p><p>2. 会社員</p><p>3. じゃありません</p><p>4. さくら</p><h3>Bài tập củng cố</h3><p>• Bài 1: <code>は</code>, <code>は</code>, <code>の</code>, <code>は</code>.</p><p>• Bài 2: <code>私は 医者じゃありません。</code>; <code>リーさんは 日本人じゃありません。</code>; <code>マイさんは 学生じゃありません。</code></p><p>• Bài 3: <code>私は 会社員です。</code>; <code>田中さんは 日本人ですか。</code>; <code>さくら大学の 学生です。</code>; <code>アンさんも エンジニアです。</code></p></div>', 'EXERCISE'),
(1, 12, 'Bài tập về nhà', 'Thu âm một đoạn tự giới thiệu dài khoảng 30-45 giây. Nội dung cần có lời chào, tên, quốc tịch, nghề nghiệp hoặc trường/công ty và câu よろしく おねがいします.', '<div class="n5-lesson-content"><p>Thu âm một đoạn tự giới thiệu dài khoảng 30-45 giây. Nội dung cần có lời chào, tên, quốc tịch, nghề nghiệp hoặc trường/công ty và câu <code>よろしく おねがいします</code>.</p></div>', 'EXERCISE'),
(2, 1, 'Mục tiêu Can-do', 'Chỉ và gọi tên đồ vật ở gần hoặc xa người nói/người nghe.', '<div class="n5-lesson-content"><p>• Chỉ và gọi tên đồ vật ở gần hoặc xa người nói/người nghe.</p><p>• Hỏi đồ vật là gì, của ai hoặc thuộc loại nào.</p><p>• Đặt câu hỏi lựa chọn giữa hai đáp án.</p></div>', 'LESSON'),
(2, 2, 'Từ vựng', 'これ cái này; それ cái đó; あれ cái kia; この～ ~ này; その～ ~ đó; あの～ ~ kia; 何（なん） cái gì; 本（ほん） sách; 辞書（じしょ） từ điển; 新聞（しんぶん） báo; かばん cặp; 傘（かさ） ô; 時計（とけい） đồng hồ; 名刺（めいし） danh thiếp; お土産（おみやげ） quà.', '<div class="n5-lesson-content"><p><code>これ</code> cái này; <code>それ</code> cái đó; <code>あれ</code> cái kia; <code>この～</code> ~ này; <code>その～</code> ~ đó; <code>あの～</code> ~ kia; <code>何（なん）</code> cái gì; <code>本（ほん）</code> sách; <code>辞書（じしょ）</code> từ điển; <code>新聞（しんぶん）</code> báo; <code>かばん</code> cặp; <code>傘（かさ）</code> ô; <code>時計（とけい）</code> đồng hồ; <code>名刺（めいし）</code> danh thiếp; <code>お土産（おみやげ）</code> quà.</p></div>', 'VOCABULARY'),
(2, 3, 'Ngữ pháp', 'これ gần người nói, それ gần người nghe, あれ xa cả hai.', '<div class="n5-lesson-content"><h3><code>これ／それ／あれ は N です</code></h3><p><code>これ</code> gần người nói, <code>それ</code> gần người nghe, <code>あれ</code> xa cả hai.</p><p>• これは 日本語の本です。- Đây là sách tiếng Nhật.</p><p>• あれは 山田さんの傘です。- Kia là ô của anh Yamada.</p><h3><code>N1 の N2</code></h3><p>Biểu thị sở hữu hoặc nội dung: <code>私の時計</code> đồng hồ của tôi; <code>日本語の辞書</code> từ điển tiếng Nhật.</p><h3><code>この／その／あの N</code></h3><p>Ba từ này luôn đứng trước danh từ: <code>この本</code>, <code>そのかばん</code>, <code>あの時計</code>.</p><h3><code>N1 ですか、N2 ですか</code></h3><p>• これは 新聞ですか、雑誌ですか。- Đây là báo hay tạp chí?</p><p>• 雑誌です。- Là tạp chí.</p></div>', 'GRAMMAR'),
(2, 4, 'Đọc hiểu', 'これは ミラーさんのかばんです。その中に日本語の本と英語の辞書があります。あの傘はミラーさんのではありません。佐藤さんのです。', '<div class="n5-lesson-content"><blockquote>これは ミラーさんのかばんです。その中に日本語の本と英語の辞書があります。あの傘はミラーさんのではありません。佐藤さんのです。</blockquote><p>1. Cặp là của ai? 2. Trong cặp có gì? 3. Chiếc ô có phải của Miller không?</p></div>', 'LESSON'),
(2, 5, 'Nghe và hội thoại', 'Giáo viên đọc hai lần:', '<div class="n5-lesson-content"><p>Giáo viên đọc hai lần:</p><p>A: すみません。それは何ですか。</p><p>B: これは家族の写真です。</p><p>A: この人はお母さんですか、お姉さんですか。</p><p>B: 姉です。</p><p>Nhiệm vụ: ghi tên đồ vật và quan hệ của người trong ảnh; sau đó thay <code>写真</code> bằng một đồ vật khác để luyện theo cặp.</p></div>', 'LISTENING'),
(2, 6, 'Luyện tập và đáp án', 'Điền これ／それ／あれ: vật cạnh người nói -> これ; cạnh người nghe -> それ; xa cả hai -> あれ.', '<div class="n5-lesson-content"><p>1. Điền <code>これ／それ／あれ</code>: vật cạnh người nói -&gt; <code>これ</code>; cạnh người nghe -&gt; <code>それ</code>; xa cả hai -&gt; <code>あれ</code>.</p><p>2. Sắp xếp <code>です／これは／だれ／の／かばん／か</code> -&gt; <code>これはだれのかばんですか。</code></p><p>3. Dịch “Quyển từ điển này là từ điển tiếng Nhật hay tiếng Anh?” -&gt; <code>この辞書は日本語の辞書ですか、英語の辞書ですか。</code></p></div>', 'EXERCISE'),
(3, 1, 'Mục tiêu Can-do', 'Hỏi và chỉ vị trí của người, đồ vật và địa điểm.', '<div class="n5-lesson-content"><p>• Hỏi và chỉ vị trí của người, đồ vật và địa điểm.</p><p>• Hỏi tầng, nơi sản xuất và giá tiền.</p><p>• Giao tiếp đơn giản tại cửa hàng.</p></div>', 'LESSON'),
(3, 2, 'Từ vựng', 'ここ đây; そこ đó; あそこ kia; どこ đâu; こちら／そちら／あちら／どちら dạng lịch sự; 教室（きょうしつ） lớp học; 事務所（じむしょ） văn phòng; 受付（うけつけ） quầy lễ tân; 食堂（しょくどう） nhà ăn; 売り場（うりば） quầy bán hàng; 階（かい） tầng; いくら bao nhiêu tiền; 円（えん） yên.', '<div class="n5-lesson-content"><p><code>ここ</code> đây; <code>そこ</code> đó; <code>あそこ</code> kia; <code>どこ</code> đâu; <code>こちら／そちら／あちら／どちら</code> dạng lịch sự; <code>教室（きょうしつ）</code> lớp học; <code>事務所（じむしょ）</code> văn phòng; <code>受付（うけつけ）</code> quầy lễ tân; <code>食堂（しょくどう）</code> nhà ăn; <code>売り場（うりば）</code> quầy bán hàng; <code>階（かい）</code> tầng; <code>いくら</code> bao nhiêu tiền; <code>円（えん）</code> yên.</p></div>', 'VOCABULARY'),
(3, 3, 'Ngữ pháp', 'ここは受付です。- Đây là quầy lễ tân.', '<div class="n5-lesson-content"><h3><code>ここ／そこ／あそこ は N です</code></h3><p>• ここは受付です。- Đây là quầy lễ tân.</p><p>• あそこは図書館です。- Kia là thư viện.</p><h3><code>N は địa điểm です</code></h3><p>• トイレは二階です。- Nhà vệ sinh ở tầng hai.</p><p>• 先生は事務所です。- Giáo viên ở văn phòng.</p><h3><code>どこ／どちら</code></h3><p>• エレベーターはどこですか。- Thang máy ở đâu?</p><p>• お国はどちらですか。- Anh/chị đến từ nước nào?</p><h3>Xuất xứ và giá tiền</h3><p>• これはどこの時計ですか。日本の時計です。- Đồng hồ này của nước nào? Của Nhật.</p><p>• このかばんはいくらですか。3,000円です。- Cặp này bao nhiêu? 3.000 yên.</p></div>', 'GRAMMAR'),
(3, 4, 'Đọc hiểu', 'デパートの一階は食品売り場です。二階は服の売り場です。カフェは七階です。カフェのコーヒーは400円です。', '<div class="n5-lesson-content"><blockquote>デパートの一階は食品売り場です。二階は服の売り場です。カフェは七階です。カフェのコーヒーは400円です。</blockquote><p>1. Quầy thực phẩm ở tầng nào? 2. Quầy quần áo ở đâu? 3. Cà phê giá bao nhiêu?</p></div>', 'LESSON'),
(3, 5, 'Nghe và hội thoại', 'A: すみません。靴の売り場は何階ですか。', '<div class="n5-lesson-content"><p>A: すみません。靴の売り場は何階ですか。</p><p>B: 三階です。</p><p>A: この靴はいくらですか。</p><p>B: 5,000円です。</p><p>Nhiệm vụ: ghi tầng và giá, rồi đóng vai khách hàng - nhân viên với sản phẩm khác.</p></div>', 'LISTENING'),
(3, 6, 'Đáp án', 'Đọc: 一階, 二階, 400円.', '<div class="n5-lesson-content"><p>• Đọc: <code>一階</code>, <code>二階</code>, <code>400円</code>.</p><p>• Mẫu hỏi lịch sự “Quầy lễ tân ở đâu?”: <code>受付はどちらですか。</code></p></div>', 'EXERCISE'),
(4, 1, 'Mục tiêu Can-do', 'Hỏi và trả lời giờ, phút, thứ trong tuần.', '<div class="n5-lesson-content"><p>• Hỏi và trả lời giờ, phút, thứ trong tuần.</p><p>• Nói thời điểm thực hiện một hành động.</p><p>• Nói thời gian bắt đầu và kết thúc.</p></div>', 'LESSON'),
(4, 2, 'Từ vựng', '今（いま） bây giờ; 時（じ） giờ; 分（ふん／ぷん） phút; 半（はん） rưỡi; 何時（なんじ） mấy giờ; 起きます thức dậy; 寝ます ngủ; 働きます làm việc; 勉強します học; 始まります bắt đầu; 終わります kết thúc; 午前（ごぜん） sáng; 午後（ごご） chiều; 休み（やすみ） nghỉ.', '<div class="n5-lesson-content"><p><code>今（いま）</code> bây giờ; <code>時（じ）</code> giờ; <code>分（ふん／ぷん）</code> phút; <code>半（はん）</code> rưỡi; <code>何時（なんじ）</code> mấy giờ; <code>起きます</code> thức dậy; <code>寝ます</code> ngủ; <code>働きます</code> làm việc; <code>勉強します</code> học; <code>始まります</code> bắt đầu; <code>終わります</code> kết thúc; <code>午前（ごぜん）</code> sáng; <code>午後（ごご）</code> chiều; <code>休み（やすみ）</code> nghỉ.</p></div>', 'VOCABULARY'),
(4, 3, 'Ngữ pháp', '今、七時半です。- Bây giờ là 7 giờ 30.', '<div class="n5-lesson-content"><h3>Giờ và phút</h3><p>• 今、七時半です。- Bây giờ là 7 giờ 30.</p><p>• 日本は今何時ですか。- Nhật Bản bây giờ là mấy giờ?</p><h3><code>N thời gian に V</code></h3><p><code>に</code> đánh dấu thời điểm cụ thể; thường bỏ sau <code>今日</code>, <code>明日</code>, <code>毎日</code>.</p><p>• 六時に起きます。- Tôi thức dậy lúc 6 giờ.</p><p>• 毎日、日本語を勉強します。- Hằng ngày tôi học tiếng Nhật.</p><h3><code>N1 から N2 まで</code></h3><p>• 銀行は九時から三時までです。- Ngân hàng mở từ 9 giờ đến 3 giờ.</p><p>• 月曜日から金曜日まで働きます。- Tôi làm từ thứ Hai đến thứ Sáu.</p></div>', 'GRAMMAR'),
(4, 4, 'Đọc hiểu', 'リンさんは毎朝六時半に起きます。学校は八時から四時までです。火曜日と木曜日の夜、日本語を勉強します。日曜日は休みです。', '<div class="n5-lesson-content"><blockquote>リンさんは毎朝六時半に起きます。学校は八時から四時までです。火曜日と木曜日の夜、日本語を勉強します。日曜日は休みです。</blockquote><p>1. Linh thức dậy lúc nào? 2. Trường kết thúc lúc mấy giờ? 3. Linh học tiếng Nhật thứ mấy?</p></div>', 'LESSON'),
(4, 5, 'Nghe và hội thoại', 'A: すみません。図書館は何時からですか。', '<div class="n5-lesson-content"><p>A: すみません。図書館は何時からですか。</p><p>B: 午前八時半からです。</p><p>A: 何時までですか。</p><p>B: 午後六時までです。</p><p>Nhiệm vụ: ghi giờ mở và đóng cửa; thực hành lại với bưu điện hoặc ngân hàng.</p></div>', 'LISTENING'),
(4, 6, 'Đáp án', 'Đọc: 六時半, 四時, 火曜日と木曜日.', '<div class="n5-lesson-content"><p>• Đọc: <code>六時半</code>, <code>四時</code>, <code>火曜日と木曜日</code>.</p><p>• <code>7:45</code> -&gt; <code>七時四十五分</code>; “Tôi ngủ lúc 11 giờ” -&gt; <code>十一時に寝ます。</code></p></div>', 'EXERCISE'),
(5, 1, 'Mục tiêu Can-do', 'Nói đi, đến hoặc về đâu.', '<div class="n5-lesson-content"><p>• Nói đi, đến hoặc về đâu.</p><p>• Nêu phương tiện, người đồng hành và thời gian di chuyển.</p><p>• Hỏi thông tin một chuyến đi.</p></div>', 'LESSON'),
(5, 2, 'Từ vựng', '行きます（いきます） đi; 来ます（きます） đến; 帰ります（かえります） về; 学校 trường; 駅（えき） ga; 電車（でんしゃ） tàu điện; 地下鉄（ちかてつ） tàu điện ngầm; バス xe buýt; 自転車（じてんしゃ） xe đạp; 歩いて（あるいて） đi bộ; 友達（ともだち） bạn; 一人で（ひとりで） một mình; いつ khi nào.', '<div class="n5-lesson-content"><p><code>行きます（いきます）</code> đi; <code>来ます（きます）</code> đến; <code>帰ります（かえります）</code> về; <code>学校</code> trường; <code>駅（えき）</code> ga; <code>電車（でんしゃ）</code> tàu điện; <code>地下鉄（ちかてつ）</code> tàu điện ngầm; <code>バス</code> xe buýt; <code>自転車（じてんしゃ）</code> xe đạp; <code>歩いて（あるいて）</code> đi bộ; <code>友達（ともだち）</code> bạn; <code>一人で（ひとりで）</code> một mình; <code>いつ</code> khi nào.</p></div>', 'VOCABULARY'),
(5, 3, 'Ngữ pháp', '毎日、学校へ行きます。- Hằng ngày tôi đến trường.', '<div class="n5-lesson-content"><h3><code>N địa điểm へ 行きます／来ます／帰ります</code></h3><p>• 毎日、学校へ行きます。- Hằng ngày tôi đến trường.</p><p>• 来月、日本へ来ます。- Tháng sau tôi đến Nhật.</p><h3><code>N phương tiện で</code></h3><p>• 電車で会社へ行きます。- Tôi đi công ty bằng tàu điện.</p><p>• <code>歩いて</code> không dùng <code>で</code>: 駅まで歩いて行きます。</p><h3><code>N người と</code></h3><p>• 友達と京都へ行きます。- Tôi đi Kyoto với bạn.</p><p>• 一人で帰ります。- Tôi về một mình.</p><h3><code>N thời gian に</code></h3><p>• 七月二日に大阪へ行きます。- Tôi đi Osaka ngày 2 tháng 7.</p></div>', 'GRAMMAR'),
(5, 4, 'Đọc hiểu', '日曜日に家族と京都へ行きます。朝七時に家を出ます。駅までバスで行きます。京都へは電車で行きます。夜九時に帰ります。', '<div class="n5-lesson-content"><blockquote>日曜日に家族と京都へ行きます。朝七時に家を出ます。駅までバスで行きます。京都へは電車で行きます。夜九時に帰ります。</blockquote><p>1. Đi cùng ai? 2. Ra khỏi nhà lúc nào? 3. Đi tới Kyoto bằng gì?</p></div>', 'LESSON'),
(5, 5, 'Nghe và hội thoại', 'A: 夏休みにどこへ行きますか。', '<div class="n5-lesson-content"><p>A: 夏休みにどこへ行きますか。</p><p>B: 友達と北海道へ行きます。</p><p>A: 何で行きますか。</p><p>B: 飛行機で行きます。</p><p>Nhiệm vụ: lập kế hoạch chuyến đi gồm nơi đến, ngày đi, phương tiện và người đồng hành.</p></div>', 'LISTENING'),
(5, 6, 'Đáp án', 'Đọc: 家族と, 朝七時, 電車で.', '<div class="n5-lesson-content"><p>• Đọc: <code>家族と</code>, <code>朝七時</code>, <code>電車で</code>.</p><p>• “Tôi về nhà bằng xe buýt” -&gt; <code>バスで家へ帰ります。</code></p></div>', 'EXERCISE'),
(6, 1, 'Mục tiêu Can-do', 'Nói hành động tác động lên một đối tượng.', '<div class="n5-lesson-content"><p>• Nói hành động tác động lên một đối tượng.</p><p>• Nói nơi diễn ra hành động.</p><p>• Mời, nhận lời hoặc từ chối một cách lịch sự.</p></div>', 'LESSON'),
(6, 2, 'Từ vựng', '食べます（たべます） ăn; 飲みます（のみます） uống; 見ます（みます） xem; 読みます（よみます） đọc; 書きます（かきます） viết; 買います（かいます） mua; 撮ります（とります） chụp; 会います（あいます） gặp; 朝ご飯 bữa sáng; 昼ご飯 bữa trưa; 晩ご飯 bữa tối; 映画（えいが） phim; 一緒に（いっしょに） cùng nhau.', '<div class="n5-lesson-content"><p><code>食べます（たべます）</code> ăn; <code>飲みます（のみます）</code> uống; <code>見ます（みます）</code> xem; <code>読みます（よみます）</code> đọc; <code>書きます（かきます）</code> viết; <code>買います（かいます）</code> mua; <code>撮ります（とります）</code> chụp; <code>会います（あいます）</code> gặp; <code>朝ご飯</code> bữa sáng; <code>昼ご飯</code> bữa trưa; <code>晩ご飯</code> bữa tối; <code>映画（えいが）</code> phim; <code>一緒に（いっしょに）</code> cùng nhau.</p></div>', 'VOCABULARY'),
(6, 3, 'Ngữ pháp', 'を đánh dấu đối tượng của hành động.', '<div class="n5-lesson-content"><h3><code>N を Vます</code></h3><p><code>を</code> đánh dấu đối tượng của hành động.</p><p>• コーヒーを飲みます。- Tôi uống cà phê.</p><p>• 本を読みません。- Tôi không đọc sách.</p><h3><code>N địa điểm で Vます</code></h3><p>• 食堂で昼ご飯を食べます。- Tôi ăn trưa tại nhà ăn.</p><p>• 駅で友達に会います。- Tôi gặp bạn ở ga.</p><h3><code>Vませんか</code></h3><p>• 一緒に映画を見ませんか。- Bạn xem phim cùng tôi nhé?</p><p>• はい、見ましょう。- Vâng, cùng xem nhé.</p><p>• すみません、今日はちょっと…。- Xin lỗi, hôm nay hơi bất tiện...</p></div>', 'GRAMMAR'),
(6, 4, 'Đọc hiểu', '土曜日に友達とデパートへ行きます。レストランでラーメンを食べます。それから映画館で日本の映画を見ます。', '<div class="n5-lesson-content"><blockquote>土曜日に友達とデパートへ行きます。レストランでラーメンを食べます。それから映画館で日本の映画を見ます。</blockquote><p>1. Đi đâu vào thứ Bảy? 2. Ăn gì ở đâu? 3. Sau đó làm gì?</p></div>', 'LESSON'),
(6, 5, 'Nghe và hội thoại', 'A: 今晩、一緒に晩ご飯を食べませんか。', '<div class="n5-lesson-content"><p>A: 今晩、一緒に晩ご飯を食べませんか。</p><p>B: いいですね。どこで食べますか。</p><p>A: 駅の近くのレストランで食べましょう。</p><p>Nhiệm vụ: ghi thời gian, hoạt động và địa điểm; thay thông tin để mời bạn cùng làm một việc.</p></div>', 'LISTENING'),
(6, 6, 'Đáp án', 'Đọc: デパート, レストランでラーメン, 日本の映画を見ます.', '<div class="n5-lesson-content"><p>• Đọc: <code>デパート</code>, <code>レストランでラーメン</code>, <code>日本の映画を見ます</code>.</p><p>• “Tôi mua sách ở nhà sách” -&gt; <code>本屋で本を買います。</code></p></div>', 'EXERCISE'),
(7, 1, 'Mục tiêu Can-do', 'Nói công cụ hoặc ngôn ngữ dùng để thực hiện hành động.', '<div class="n5-lesson-content"><p>• Nói công cụ hoặc ngôn ngữ dùng để thực hiện hành động.</p><p>• Diễn đạt việc cho và nhận đồ vật.</p><p>• Hỏi một hành động đã hoàn thành chưa.</p></div>', 'LESSON'),
(7, 2, 'Từ vựng', '切ります（きります） cắt; 送ります（おくります） gửi; あげます cho; もらいます nhận; 貸します（かします） cho mượn; 借ります（かります） mượn; 教えます（おしえます） dạy; 習います（ならいます） học từ ai; 箸（はし） đũa; はさみ kéo; プレゼント quà; 花（はな） hoa; もう đã rồi; まだ vẫn chưa.', '<div class="n5-lesson-content"><p><code>切ります（きります）</code> cắt; <code>送ります（おくります）</code> gửi; <code>あげます</code> cho; <code>もらいます</code> nhận; <code>貸します（かします）</code> cho mượn; <code>借ります（かります）</code> mượn; <code>教えます（おしえます）</code> dạy; <code>習います（ならいます）</code> học từ ai; <code>箸（はし）</code> đũa; <code>はさみ</code> kéo; <code>プレゼント</code> quà; <code>花（はな）</code> hoa; <code>もう</code> đã rồi; <code>まだ</code> vẫn chưa.</p></div>', 'VOCABULARY'),
(7, 3, 'Ngữ pháp', 'はさみで紙を切ります。- Tôi cắt giấy bằng kéo.', '<div class="n5-lesson-content"><h3><code>N công cụ で Vます</code></h3><p>• はさみで紙を切ります。- Tôi cắt giấy bằng kéo.</p><p>• 日本語でメールを書きます。- Tôi viết email bằng tiếng Nhật.</p><h3><code>A は B に N を あげます</code></h3><p>• 私は母に花をあげました。- Tôi đã tặng hoa cho mẹ.</p><p>• Khi người nhận là “tôi”, thường dùng <code>くれます</code> ở bài sau.</p><h3><code>A は B に／から N を もらいます</code></h3><p>• 私は友達に本をもらいました。- Tôi nhận sách từ bạn.</p><p>• 会社からプレゼントをもらいました。- Tôi nhận quà từ công ty.</p><h3><code>もう Vました</code></h3><p>• もう宿題をしましたか。- Bạn làm bài tập xong chưa?</p><p>• はい、もうしました。／いいえ、まだです。</p></div>', 'GRAMMAR'),
(7, 4, 'Đọc hiểu', '昨日は母の誕生日でした。私は母に花をあげました。父は母に時計をあげました。私は姉にケーキをもらいました。みんなで箸とスプーンを使って食べました。', '<div class="n5-lesson-content"><blockquote>昨日は母の誕生日でした。私は母に花をあげました。父は母に時計をあげました。私は姉にケーキをもらいました。みんなで箸とスプーンを使って食べました。</blockquote><p>1. Ai nhận hoa? 2. Bố tặng gì? 3. Người kể nhận bánh từ ai?</p></div>', 'LESSON'),
(7, 5, 'Nghe và hội thoại', 'A: もうレポートを送りましたか。', '<div class="n5-lesson-content"><p>A: もうレポートを送りましたか。</p><p>B: はい、メールで先生に送りました。</p><p>A: 日本語で書きましたか。</p><p>B: はい、田中さんに日本語を教えてもらいました。</p><p>Nhiệm vụ: xác định phương tiện, người nhận và người giúp; sau đó kể về một món quà từng cho hoặc nhận.</p></div>', 'LISTENING'),
(7, 6, 'Đáp án', 'Đọc: 母, 時計, 姉.', '<div class="n5-lesson-content"><p>• Đọc: <code>母</code>, <code>時計</code>, <code>姉</code>.</p><p>• “Tôi nhận từ điển từ giáo viên” -&gt; <code>私は先生に辞書をもらいました。</code></p></div>', 'EXERCISE'),
(8, 1, 'Mục tiêu Can-do', 'Miêu tả người, vật và địa điểm bằng tính từ.', '<div class="n5-lesson-content"><p>• Miêu tả người, vật và địa điểm bằng tính từ.</p><p>• Nối hai nhận xét bổ sung hoặc tương phản.</p><p>• Đặt tính từ trước danh từ.</p></div>', 'LESSON'),
(8, 2, 'Từ vựng', 'Tính từ い: 大きい lớn; 小さい nhỏ; 新しい mới; 古い cũ; 暑い nóng; 寒い lạnh; 高い cao/đắt; 安い rẻ; おもしろい thú vị. Tính từ な: きれい đẹp/sạch; 静か yên tĩnh; にぎやか nhộn nhịp; 親切 tốt bụng; 元気 khỏe mạnh; 便利 tiện lợi; 有名 nổi tiếng.', '<div class="n5-lesson-content"><p>Tính từ <code>い</code>: <code>大きい</code> lớn; <code>小さい</code> nhỏ; <code>新しい</code> mới; <code>古い</code> cũ; <code>暑い</code> nóng; <code>寒い</code> lạnh; <code>高い</code> cao/đắt; <code>安い</code> rẻ; <code>おもしろい</code> thú vị. Tính từ <code>な</code>: <code>きれい</code> đẹp/sạch; <code>静か</code> yên tĩnh; <code>にぎやか</code> nhộn nhịp; <code>親切</code> tốt bụng; <code>元気</code> khỏe mạnh; <code>便利</code> tiện lợi; <code>有名</code> nổi tiếng.</p></div>', 'VOCABULARY'),
(8, 3, 'Ngữ pháp', '富士山は高いです。- Núi Phú Sĩ cao.', '<div class="n5-lesson-content"><h3>Câu với tính từ</h3><p>• 富士山は高いです。- Núi Phú Sĩ cao.</p><p>• 京都は静かです。- Kyoto yên tĩnh.</p><p>• この町はにぎやかじゃありません。- Thành phố này không nhộn nhịp.</p><h3>Tính từ bổ nghĩa danh từ</h3><p>• <code>おもしろい映画</code> bộ phim thú vị.</p><p>• <code>きれいな町</code> thành phố đẹp. Tính từ <code>な</code> cần <code>な</code> trước danh từ.</p><h3><code>そして</code> và <code>～が、～</code></h3><p>• この店は安いです。そして、おいしいです。- Quán này rẻ và ngon.</p><p>• 日本語はおもしろいですが、難しいです。- Tiếng Nhật thú vị nhưng khó.</p></div>', 'GRAMMAR'),
(8, 4, 'Đọc hiểu', '私の町は小さいですが、きれいです。駅の近くはにぎやかです。そして、便利です。町の公園は静かな場所です。', '<div class="n5-lesson-content"><blockquote>私の町は小さいですが、きれいです。駅の近くはにぎやかです。そして、便利です。町の公園は静かな場所です。</blockquote><p>1. Thành phố lớn hay nhỏ? 2. Khu vực gần ga thế nào? 3. Công viên là nơi như thế nào?</p></div>', 'LESSON'),
(8, 5, 'Nghe và hội thoại', 'A: 日本の生活はどうですか。', '<div class="n5-lesson-content"><p>A: 日本の生活はどうですか。</p><p>B: 便利です。そして、食べ物がおいしいです。でも、冬はとても寒いです。</p><p>Nhiệm vụ: ghi hai điểm tích cực và một điểm tương phản; giới thiệu nơi mình sống bằng ba tính từ.</p></div>', 'LISTENING'),
(8, 6, 'Đáp án', 'Đọc: 小さい, にぎやかで便利, 静かな場所.', '<div class="n5-lesson-content"><p>• Đọc: <code>小さい</code>, <code>にぎやかで便利</code>, <code>静かな場所</code>.</p><p>• <code>便利 + 町</code> -&gt; <code>便利な町</code>; phủ định của <code>高いです</code> -&gt; <code>高くないです</code>.</p></div>', 'EXERCISE'),
(9, 1, 'Mục tiêu Can-do', 'Nói sở thích, sở trường và mức độ hiểu biết.', '<div class="n5-lesson-content"><p>• Nói sở thích, sở trường và mức độ hiểu biết.</p><p>• Hỏi người khác thích loại sự vật nào.</p><p>• Nêu nguyên nhân bằng <code>から</code>.</p></div>', 'LESSON'),
(9, 2, 'Từ vựng', '好き（すき） thích; 嫌い（きらい） ghét; 上手（じょうず） giỏi; 下手（へた） kém; 分かります（わかります） hiểu; あります có; 料理（りょうり） món ăn/nấu ăn; 音楽（おんがく） âm nhạc; スポーツ thể thao; 野球（やきゅう） bóng chày; 漢字（かんじ） chữ Hán; よく tốt/thường; 少し（すこし） một ít; 全然（ぜんぜん） hoàn toàn không.', '<div class="n5-lesson-content"><p><code>好き（すき）</code> thích; <code>嫌い（きらい）</code> ghét; <code>上手（じょうず）</code> giỏi; <code>下手（へた）</code> kém; <code>分かります（わかります）</code> hiểu; <code>あります</code> có; <code>料理（りょうり）</code> món ăn/nấu ăn; <code>音楽（おんがく）</code> âm nhạc; <code>スポーツ</code> thể thao; <code>野球（やきゅう）</code> bóng chày; <code>漢字（かんじ）</code> chữ Hán; <code>よく</code> tốt/thường; <code>少し（すこし）</code> một ít; <code>全然（ぜんぜん）</code> hoàn toàn không.</p></div>', 'VOCABULARY'),
(9, 3, 'Ngữ pháp', '私は日本料理が好きです。- Tôi thích món Nhật.', '<div class="n5-lesson-content"><h3><code>N が 好き／嫌い／上手／下手です</code></h3><p>• 私は日本料理が好きです。- Tôi thích món Nhật.</p><p>• 弟は歌が上手じゃありません。- Em trai tôi hát không giỏi.</p><h3><code>N が 分かります／あります</code></h3><p>• 日本語が少し分かります。- Tôi hiểu một chút tiếng Nhật.</p><p>• 車があります。- Tôi có ô tô.</p><h3><code>どんな N が A ですか</code></h3><p>• どんな音楽が好きですか。- Bạn thích loại nhạc nào?</p><p>• ジャズが好きです。- Tôi thích nhạc jazz.</p><h3><code>～から、～</code></h3><p>• 辛い食べ物が苦手ですから、食べません。- Vì không hợp đồ cay nên tôi không ăn.</p></div>', 'GRAMMAR'),
(9, 4, 'Đọc hiểu', 'アンさんはスポーツが好きです。テニスが上手ですが、水泳はあまり上手じゃありません。音楽も好きですから、毎晩ギターを練習します。', '<div class="n5-lesson-content"><blockquote>アンさんはスポーツが好きです。テニスが上手ですが、水泳はあまり上手じゃありません。音楽も好きですから、毎晩ギターを練習します。</blockquote><p>1. An thích gì? 2. Môn nào An chưa giỏi? 3. Vì sao tối nào An cũng tập guitar?</p></div>', 'LESSON'),
(9, 5, 'Nghe và hội thoại', 'A: どんな料理が好きですか。', '<div class="n5-lesson-content"><p>A: どんな料理が好きですか。</p><p>B: ベトナム料理が好きです。フォーがとても好きです。</p><p>A: 日本料理も好きですか。</p><p>B: はい、好きですが、納豆はちょっと…。</p><p>Nhiệm vụ: ghi món thích và không thích; phỏng vấn bạn về món ăn, thể thao hoặc âm nhạc.</p></div>', 'LISTENING'),
(9, 6, 'Đáp án', 'Đọc: スポーツと音楽, 水泳, 音楽が好きですから.', '<div class="n5-lesson-content"><p>• Đọc: <code>スポーツと音楽</code>, <code>水泳</code>, <code>音楽が好きですから</code>.</p><p>• “Tôi hoàn toàn không hiểu tiếng Trung” -&gt; <code>中国語が全然分かりません。</code></p></div>', 'EXERCISE'),
(10, 1, 'Mục tiêu Can-do', 'Nói sự tồn tại của người, động vật và đồ vật.', '<div class="n5-lesson-content"><p>• Nói sự tồn tại của người, động vật và đồ vật.</p><p>• Miêu tả vị trí tương đối.</p><p>• Liệt kê một số đối tượng tiêu biểu.</p></div>', 'LESSON'),
(10, 2, 'Từ vựng', 'あります có, dùng cho vật; います có, dùng cho người/động vật; 上（うえ） trên; 下（した） dưới; 前（まえ） trước; 後ろ（うしろ） sau; 右（みぎ） phải; 左（ひだり） trái; 中（なか） trong; 外（そと） ngoài; 隣（となり） bên cạnh; 近く（ちかく） gần; 間（あいだ） giữa; 猫（ねこ） mèo; 犬（いぬ） chó.', '<div class="n5-lesson-content"><p><code>あります</code> có, dùng cho vật; <code>います</code> có, dùng cho người/động vật; <code>上（うえ）</code> trên; <code>下（した）</code> dưới; <code>前（まえ）</code> trước; <code>後ろ（うしろ）</code> sau; <code>右（みぎ）</code> phải; <code>左（ひだり）</code> trái; <code>中（なか）</code> trong; <code>外（そと）</code> ngoài; <code>隣（となり）</code> bên cạnh; <code>近く（ちかく）</code> gần; <code>間（あいだ）</code> giữa; <code>猫（ねこ）</code> mèo; <code>犬（いぬ）</code> chó.</p></div>', 'VOCABULARY'),
(10, 3, 'Ngữ pháp', '教室にテレビがあります。- Trong lớp có tivi.', '<div class="n5-lesson-content"><h3><code>N が あります／います</code></h3><p>• 教室にテレビがあります。- Trong lớp có tivi.</p><p>• 公園に子どもがいます。- Trong công viên có trẻ em.</p><h3><code>N1 の N2 vị trí</code></h3><p>• 机の上 - trên bàn; <code>銀行の隣</code> - bên cạnh ngân hàng.</p><h3>Câu tồn tại và câu vị trí</h3><p>• 駅の前にコンビニがあります。- Trước ga có cửa hàng tiện lợi.</p><p>• コンビニは駅の前にあります。- Cửa hàng tiện lợi nằm trước ga.</p><h3><code>N1 や N2 など</code></h3><p>• 箱の中に写真や手紙などがあります。- Trong hộp có ảnh, thư và những thứ khác.</p></div>', 'GRAMMAR'),
(10, 4, 'Đọc hiểu', '私の部屋には机とベッドがあります。机の上にパソコンがあります。ベッドの下に猫がいます。本棚には日本語の本や辞書などがあります。', '<div class="n5-lesson-content"><blockquote>私の部屋には机とベッドがあります。机の上にパソコンがあります。ベッドの下に猫がいます。本棚には日本語の本や辞書などがあります。</blockquote><p>1. Máy tính ở đâu? 2. Con mèo ở đâu? 3. Trên giá sách có gì?</p></div>', 'LESSON'),
(10, 5, 'Nghe và hội thoại', 'A: すみません、郵便局はどこですか。', '<div class="n5-lesson-content"><p>A: すみません、郵便局はどこですか。</p><p>B: 駅の右に銀行があります。郵便局は銀行とスーパーの間にあります。</p><p>Nhiệm vụ: vẽ sơ đồ theo lời chỉ dẫn; sau đó dùng sơ đồ để hỏi và chỉ đường.</p></div>', 'LISTENING'),
(10, 6, 'Đáp án', 'Đọc: 机の上, ベッドの下, 日本語の本や辞書など.', '<div class="n5-lesson-content"><p>• Đọc: <code>机の上</code>, <code>ベッドの下</code>, <code>日本語の本や辞書など</code>.</p><p>• Chọn đúng: chó -&gt; <code>います</code>; ghế -&gt; <code>あります</code>.</p></div>', 'EXERCISE'),
(11, 1, 'Mục tiêu Can-do', 'Đếm người, đồ vật và phương tiện bằng lượng từ phù hợp.', '<div class="n5-lesson-content"><p>• Đếm người, đồ vật và phương tiện bằng lượng từ phù hợp.</p><p>• Nói thời lượng của một hoạt động.</p><p>• Nói tần suất trong một khoảng thời gian.</p></div>', 'LESSON'),
(11, 2, 'Từ vựng', '一つ～十 một đến mười đồ vật chung; 一人／二人／～人 người; 一枚（まい） vật mỏng; 一台（だい） máy/xe; 一冊（さつ） quyển; 一回（かい） lần; 何個（なんこ） bao nhiêu cái; 何人（なんにん） bao nhiêu người; 時間（じかん） giờ; 週間（しゅうかん） tuần; かかります mất thời gian/chi phí; ぐらい khoảng.', '<div class="n5-lesson-content"><p><code>一つ～十</code> một đến mười đồ vật chung; <code>一人／二人／～人</code> người; <code>一枚（まい）</code> vật mỏng; <code>一台（だい）</code> máy/xe; <code>一冊（さつ）</code> quyển; <code>一回（かい）</code> lần; <code>何個（なんこ）</code> bao nhiêu cái; <code>何人（なんにん）</code> bao nhiêu người; <code>時間（じかん）</code> giờ; <code>週間（しゅうかん）</code> tuần; <code>かかります</code> mất thời gian/chi phí; <code>ぐらい</code> khoảng.</p></div>', 'VOCABULARY'),
(11, 3, 'Ngữ pháp', 'りんごを三つ買いました。- Tôi mua ba quả táo.', '<div class="n5-lesson-content"><h3><code>N を số lượng Vます</code></h3><p>• りんごを三つ買いました。- Tôi mua ba quả táo.</p><p>• クラスに学生が二十人います。- Trong lớp có 20 học viên.</p><h3>Khoảng thời gian</h3><p>• 毎日二時間日本語を勉強します。- Mỗi ngày tôi học tiếng Nhật hai giờ.</p><p>• 大阪まで三時間かかります。- Đến Osaka mất ba giờ.</p><h3>Tần suất</h3><p>• 一週間に三回運動します。- Tôi tập thể thao ba lần mỗi tuần.</p><p>• 一か月に一回映画を見ます。- Tôi xem phim một lần mỗi tháng.</p></div>', 'GRAMMAR'),
(11, 4, 'Đọc hiểu', '私のクラスには学生が十二人います。授業は一週間に三回あります。一回の授業は二時間です。家から学校まで電車で四十分かかります。', '<div class="n5-lesson-content"><blockquote>私のクラスには学生が十二人います。授業は一週間に三回あります。一回の授業は二時間です。家から学校まで電車で四十分かかります。</blockquote><p>1. Lớp có bao nhiêu người? 2. Mỗi tuần học mấy buổi? 3. Mỗi buổi bao lâu? 4. Đi học mất bao lâu?</p></div>', 'LESSON'),
(11, 5, 'Nghe và hội thoại', 'A: 日本語をどのくらい勉強しましたか。', '<div class="n5-lesson-content"><p>A: 日本語をどのくらい勉強しましたか。</p><p>B: 六か月勉強しました。毎日一時間ぐらい勉強します。</p><p>A: 漢字をいくつ覚えましたか。</p><p>B: 百ぐらいです。</p><p>Nhiệm vụ: ghi thời gian học mỗi ngày và tổng thời gian đã học; hỏi bạn về thói quen học tập.</p></div>', 'LISTENING'),
(11, 6, 'Đáp án', 'Đọc: 十二人, 三回, 二時間, 四十分.', '<div class="n5-lesson-content"><p>• Đọc: <code>十二人</code>, <code>三回</code>, <code>二時間</code>, <code>四十分</code>.</p><p>• <code>2 người</code> -&gt; <code>二人</code>; <code>3 quyển sách</code> -&gt; <code>本を三冊</code>.</p></div>', 'EXERCISE'),
(12, 1, 'Mục tiêu Can-do', 'Chia tính từ và danh từ ở quá khứ.', '<div class="n5-lesson-content"><p>• Chia tính từ và danh từ ở quá khứ.</p><p>• So sánh hơn giữa hai đối tượng.</p><p>• Hỏi lựa chọn và nói mức độ cao nhất trong một nhóm.</p></div>', 'LESSON'),
(12, 2, 'Từ vựng', '簡単（かんたん） đơn giản; 近い（ちかい） gần; 遠い（とおい） xa; 早い（はやい） sớm/nhanh; 遅い（おそい） muộn/chậm; 多い（おおい） nhiều; 少ない（すくない） ít; 暖かい（あたたかい） ấm; 涼しい（すずしい） mát; 季節（きせつ） mùa; 一番（いちばん） nhất; どちら bên nào.', '<div class="n5-lesson-content"><p><code>簡単（かんたん）</code> đơn giản; <code>近い（ちかい）</code> gần; <code>遠い（とおい）</code> xa; <code>早い（はやい）</code> sớm/nhanh; <code>遅い（おそい）</code> muộn/chậm; <code>多い（おおい）</code> nhiều; <code>少ない（すくない）</code> ít; <code>暖かい（あたたかい）</code> ấm; <code>涼しい（すずしい）</code> mát; <code>季節（きせつ）</code> mùa; <code>一番（いちばん）</code> nhất; <code>どちら</code> bên nào.</p></div>', 'VOCABULARY'),
(12, 3, 'Ngữ pháp', '静かです -> 静かでした; 休みです -> 休みでした.', '<div class="n5-lesson-content"><h3>Quá khứ</h3><p>• <code>静かです -&gt; 静かでした</code>; <code>休みです -&gt; 休みでした</code>.</p><p>• <code>暑いです -&gt; 暑かったです</code>; <code>よくないです -&gt; よくなかったです</code>.</p><h3><code>N1 は N2 より A です</code></h3><p>• 電車はバスより速いです。- Tàu điện nhanh hơn xe buýt.</p><h3><code>N1 と N2 と どちらが A ですか</code></h3><p>• 日本語と英語とどちらが難しいですか。日本語のほうが難しいです。</p><h3><code>N の中で N1 が一番 A です</code></h3><p>• スポーツの中でサッカーが一番好きです。- Trong các môn thể thao, tôi thích bóng đá nhất.</p></div>', 'GRAMMAR'),
(12, 4, 'Đọc hiểu', '先週、北海道と東京へ行きました。北海道は東京より寒かったです。でも、食べ物は北海道のほうがおいしかったです。旅行の中で札幌が一番楽しかったです。', '<div class="n5-lesson-content"><blockquote>先週、北海道と東京へ行きました。北海道は東京より寒かったです。でも、食べ物は北海道のほうがおいしかったです。旅行の中で札幌が一番楽しかったです。</blockquote><p>1. Nơi nào lạnh hơn? 2. Đồ ăn nơi nào ngon hơn? 3. Nơi nào vui nhất?</p></div>', 'LESSON'),
(12, 5, 'Nghe và hội thoại', 'A: 春と秋とどちらが好きですか。', '<div class="n5-lesson-content"><p>A: 春と秋とどちらが好きですか。</p><p>B: 秋のほうが好きです。涼しいですから。</p><p>A: 日本でどこが一番きれいでしたか。</p><p>B: 京都が一番きれいでした。</p><p>Nhiệm vụ: ghi lựa chọn và lý do; so sánh hai thành phố hoặc hai phương tiện.</p></div>', 'LISTENING'),
(12, 6, 'Đáp án', 'Đọc: 北海道, 北海道, 札幌.', '<div class="n5-lesson-content"><p>• Đọc: <code>北海道</code>, <code>北海道</code>, <code>札幌</code>.</p><p>• Quá khứ của <code>おもしろいです</code> -&gt; <code>おもしろかったです</code>.</p></div>', 'EXERCISE'),
(13, 1, 'Mục tiêu Can-do', 'Nói mong muốn sở hữu một đồ vật.', '<div class="n5-lesson-content"><p>• Nói mong muốn sở hữu một đồ vật.</p><p>• Nói mong muốn thực hiện một hành động.</p><p>• Nói đi đâu để thực hiện mục đích gì.</p></div>', 'LESSON'),
(13, 2, 'Từ vựng', '欲しい（ほしい） muốn có; 遊びます（あそびます） chơi; 泳ぎます（およぎます） bơi; 迎えます（むかえます） đón; 疲れます（つかれます） mệt; 結婚します（けっこんします） kết hôn; 買い物（かいもの） mua sắm; 食事（しょくじ） dùng bữa; 散歩（さんぽ） đi dạo; 週末（しゅうまつ） cuối tuần; 何か（なにか） thứ gì đó; どこか đâu đó.', '<div class="n5-lesson-content"><p><code>欲しい（ほしい）</code> muốn có; <code>遊びます（あそびます）</code> chơi; <code>泳ぎます（およぎます）</code> bơi; <code>迎えます（むかえます）</code> đón; <code>疲れます（つかれます）</code> mệt; <code>結婚します（けっこんします）</code> kết hôn; <code>買い物（かいもの）</code> mua sắm; <code>食事（しょくじ）</code> dùng bữa; <code>散歩（さんぽ）</code> đi dạo; <code>週末（しゅうまつ）</code> cuối tuần; <code>何か（なにか）</code> thứ gì đó; <code>どこか</code> đâu đó.</p></div>', 'VOCABULARY'),
(13, 3, 'Ngữ pháp', '新しいパソコンが欲しいです。- Tôi muốn có máy tính mới.', '<div class="n5-lesson-content"><h3><code>N が ほしいです</code></h3><p>• 新しいパソコンが欲しいです。- Tôi muốn có máy tính mới.</p><p>• 今、何が欲しいですか。- Bây giờ bạn muốn gì?</p><p>Không dùng mẫu này để nói mong muốn của người thứ ba khi chưa có căn cứ trực tiếp.</p><h3><code>N を Vたいです</code></h3><p>• 日本料理を食べたいです。- Tôi muốn ăn món Nhật.</p><p>• 今日は働きたくないです。- Hôm nay tôi không muốn làm việc.</p><h3><code>Địa điểm へ Vます-stem／N に 行きます</code></h3><p>• デパートへ買い物に行きます。- Tôi đến trung tâm thương mại để mua sắm.</p><p>• 日本へ日本語を勉強しに行きます。- Tôi đến Nhật để học tiếng Nhật.</p></div>', 'GRAMMAR'),
(13, 4, 'Đọc hiểu', '夏休みに沖縄へ行きたいです。海で泳ぎたいです。そして、おいしい料理を食べたいです。新しいカメラも欲しいですから、日曜日にデパートへ買い物に行きます。', '<div class="n5-lesson-content"><blockquote>夏休みに沖縄へ行きたいです。海で泳ぎたいです。そして、おいしい料理を食べたいです。新しいカメラも欲しいですから、日曜日にデパートへ買い物に行きます。</blockquote><p>1. Muốn đi đâu? 2. Muốn làm gì ở biển? 3. Vì sao Chủ nhật đi mua sắm?</p></div>', 'LESSON'),
(13, 5, 'Nghe và hội thoại', 'A: 週末、何をしたいですか。', '<div class="n5-lesson-content"><p>A: 週末、何をしたいですか。</p><p>B: 映画を見たいです。いっしょに映画館へ行きませんか。</p><p>A: いいですね。私も新しい映画を見たいです。</p><p>Nhiệm vụ: ghi hoạt động mong muốn; lập kế hoạch cuối tuần với bạn.</p></div>', 'LISTENING'),
(13, 6, 'Đáp án', 'Đọc: 沖縄, 泳ぎたいです, 新しいカメラが欲しいですから.', '<div class="n5-lesson-content"><p>• Đọc: <code>沖縄</code>, <code>泳ぎたいです</code>, <code>新しいカメラが欲しいですから</code>.</p><p>• “Tôi đến thư viện để đọc sách” -&gt; <code>図書館へ本を読みに行きます。</code></p></div>', 'EXERCISE'),
(14, 1, 'Mục tiêu Can-do', 'Chia động từ sang thể て.', '<div class="n5-lesson-content"><p>• Chia động từ sang thể <code>て</code>.</p><p>• Đưa ra yêu cầu, mô tả hành động đang diễn ra và đề nghị giúp đỡ.</p></div>', 'LESSON'),
(14, 2, 'Từ vựng', 'つけます bật; 消します（けします） tắt; 開けます（あけます） mở; 閉めます（しめます） đóng; 急ぎます（いそぎます） vội; 待ちます（まちます） đợi; 持ちます（もちます） cầm; 取ります（とります） lấy; 手伝います（てつだいます） giúp; 呼びます（よびます） gọi; 話します（はなします） nói; 使います（つかいます） dùng.', '<div class="n5-lesson-content"><p><code>つけます</code> bật; <code>消します（けします）</code> tắt; <code>開けます（あけます）</code> mở; <code>閉めます（しめます）</code> đóng; <code>急ぎます（いそぎます）</code> vội; <code>待ちます（まちます）</code> đợi; <code>持ちます（もちます）</code> cầm; <code>取ります（とります）</code> lấy; <code>手伝います（てつだいます）</code> giúp; <code>呼びます（よびます）</code> gọi; <code>話します（はなします）</code> nói; <code>使います（つかいます）</code> dùng.</p></div>', 'VOCABULARY'),
(14, 3, 'Ngữ pháp', 'Nhóm I: 書きます -> 書いて, 飲みます -> 飲んで, 話します -> 話して; riêng 行きます -> 行って.', '<div class="n5-lesson-content"><h3>Chia thể <code>て</code></h3><p>• Nhóm I: <code>書きます -&gt; 書いて</code>, <code>飲みます -&gt; 飲んで</code>, <code>話します -&gt; 話して</code>; riêng <code>行きます -&gt; 行って</code>.</p><p>• Nhóm II: bỏ <code>ます</code>, thêm <code>て</code>: <code>食べます -&gt; 食べて</code>.</p><p>• Nhóm III: <code>します -&gt; して</code>, <code>来ます -&gt; 来て</code>.</p><h3><code>Vてください</code></h3><p>• ここに名前を書いてください。- Hãy viết tên vào đây.</p><h3><code>Vています</code></h3><p>• 今、電話をかけています。- Bây giờ tôi đang gọi điện.</p><h3><code>Vましょうか</code></h3><p>• 荷物を持ちましょうか。- Tôi mang hành lý giúp nhé?</p><p>• はい、お願いします。／いいえ、大丈夫です。</p></div>', 'GRAMMAR'),
(14, 4, 'Đọc hiểu', '教室で先生が話しています。学生は教科書を読んでいます。窓が閉まっていますから、先生は「窓を開けてください」と言いました。', '<div class="n5-lesson-content"><blockquote>教室で先生が話しています。学生は教科書を読んでいます。窓が閉まっていますから、先生は「窓を開けてください」と言いました。</blockquote><p>1. Giáo viên đang làm gì? 2. Học viên đang làm gì? 3. Giáo viên yêu cầu điều gì?</p></div>', 'LESSON'),
(14, 5, 'Nghe và hội thoại', 'A: すみません、この漢字を読んでください。', '<div class="n5-lesson-content"><p>A: すみません、この漢字を読んでください。</p><p>B: はい。「駅」です。意味も説明しましょうか。</p><p>A: はい、お願いします。</p><p>Nhiệm vụ: nhận diện yêu cầu và lời đề nghị; luyện nhờ bạn mở cửa, chờ và chỉ cách đọc.</p></div>', 'LISTENING'),
(14, 6, 'Đáp án', 'Đọc: 話しています, 教科書を読んでいます, 窓を開けてください.', '<div class="n5-lesson-content"><p>• Đọc: <code>話しています</code>, <code>教科書を読んでいます</code>, <code>窓を開けてください</code>.</p><p>• Thể <code>て</code>: <code>待ちます -&gt; 待って</code>; <code>読みます -&gt; 読んで</code>; <code>来ます -&gt; 来て</code>.</p></div>', 'EXERCISE'),
(15, 1, 'Mục tiêu Can-do', 'Xin phép làm một việc.', '<div class="n5-lesson-content"><p>• Xin phép làm một việc.</p><p>• Nói quy định cấm.</p><p>• Dùng <code>ています</code> để mô tả trạng thái hoặc nghề nghiệp đang duy trì.</p></div>', 'LESSON'),
(15, 2, 'Từ vựng', '立ちます（たちます） đứng; 座ります（すわります） ngồi; 置きます（おきます） đặt; 作ります（つくります） làm/chế tạo; 売ります（うります） bán; 知ります（しります） biết; 住みます（すみます） sống; 研究します（けんきゅうします） nghiên cứu; 資料（しりょう） tài liệu; カタログ danh mục; 市役所（しやくしょ） tòa thị chính; 独身（どくしん） độc thân.', '<div class="n5-lesson-content"><p><code>立ちます（たちます）</code> đứng; <code>座ります（すわります）</code> ngồi; <code>置きます（おきます）</code> đặt; <code>作ります（つくります）</code> làm/chế tạo; <code>売ります（うります）</code> bán; <code>知ります（しります）</code> biết; <code>住みます（すみます）</code> sống; <code>研究します（けんきゅうします）</code> nghiên cứu; <code>資料（しりょう）</code> tài liệu; <code>カタログ</code> danh mục; <code>市役所（しやくしょ）</code> tòa thị chính; <code>独身（どくしん）</code> độc thân.</p></div>', 'VOCABULARY'),
(15, 3, 'Ngữ pháp', 'ここで写真を撮ってもいいですか。- Tôi chụp ảnh ở đây được không?', '<div class="n5-lesson-content"><h3><code>Vてもいいですか</code></h3><p>• ここで写真を撮ってもいいですか。- Tôi chụp ảnh ở đây được không?</p><p>• ええ、いいですよ。／すみません、ちょっと…。</p><h3><code>Vてはいけません</code></h3><p>• 教室でたばこを吸ってはいけません。- Không được hút thuốc trong lớp.</p><h3><code>Vています</code> chỉ trạng thái</h3><p>• ハノイに住んでいます。- Tôi đang sống ở Hà Nội.</p><p>• 結婚しています。- Tôi đã kết hôn.</p><p>• 車の会社で働いています。- Tôi làm việc tại công ty ô tô.</p></div>', 'GRAMMAR'),
(15, 4, 'Đọc hiểu', 'この図書館では本を読んでもいいです。パソコンも使ってもいいです。でも、食べ物を食べてはいけません。大きい声で話してはいけません。', '<div class="n5-lesson-content"><blockquote>この図書館では本を読んでもいいです。パソコンも使ってもいいです。でも、食べ物を食べてはいけません。大きい声で話してはいけません。</blockquote><p>1. Được dùng máy tính không? 2. Hai việc nào bị cấm? 3. Viết thêm một quy định phù hợp.</p></div>', 'LESSON'),
(15, 5, 'Nghe và hội thoại', 'A: 先生、この辞書を借りてもいいですか。', '<div class="n5-lesson-content"><p>A: 先生、この辞書を借りてもいいですか。</p><p>B: はい、いいですよ。でも、教室の外へ持って行ってはいけません。</p><p>Nhiệm vụ: ghi việc được phép và điều kiện cấm; đóng vai hỏi nội quy tại thư viện.</p></div>', 'LISTENING'),
(15, 6, 'Đáp án', 'Đọc: được; 食べてはいけません, 大きい声で話してはいけません.', '<div class="n5-lesson-content"><p>• Đọc: được; <code>食べてはいけません</code>, <code>大きい声で話してはいけません</code>.</p><p>• “Tôi đang sống ở TP.HCM” -&gt; <code>ホーチミン市に住んでいます。</code></p></div>', 'EXERCISE'),
(16, 1, 'Mục tiêu Can-do', 'Kể nhiều hành động theo trình tự.', '<div class="n5-lesson-content"><p>• Kể nhiều hành động theo trình tự.</p><p>• Nói hành động xảy ra sau khi hoàn tất hành động khác.</p><p>• Nối đặc điểm của người hoặc vật.</p></div>', 'LESSON'),
(16, 2, 'Từ vựng', '乗ります（のります） lên xe; 降ります（おります） xuống xe; 乗り換えます（のりかえます） chuyển tuyến; 浴びます（あびます） tắm; 入れます（いれます） cho vào; 出します（だします） lấy/gửi ra; 入ります（はいります） vào; 出ます（でます） ra; 若い（わかい） trẻ; 長い（ながい） dài; 短い（みじかい） ngắn; 明るい（あかるい） sáng/vui vẻ; 頭がいい thông minh.', '<div class="n5-lesson-content"><p><code>乗ります（のります）</code> lên xe; <code>降ります（おります）</code> xuống xe; <code>乗り換えます（のりかえます）</code> chuyển tuyến; <code>浴びます（あびます）</code> tắm; <code>入れます（いれます）</code> cho vào; <code>出します（だします）</code> lấy/gửi ra; <code>入ります（はいります）</code> vào; <code>出ます（でます）</code> ra; <code>若い（わかい）</code> trẻ; <code>長い（ながい）</code> dài; <code>短い（みじかい）</code> ngắn; <code>明るい（あかるい）</code> sáng/vui vẻ; <code>頭がいい</code> thông minh.</p></div>', 'VOCABULARY'),
(16, 3, 'Ngữ pháp', '朝起きて、顔を洗って、朝ご飯を食べます。- Tôi thức dậy, rửa mặt rồi ăn sáng.', '<div class="n5-lesson-content"><h3><code>V1て、V2て、Vます</code></h3><p>• 朝起きて、顔を洗って、朝ご飯を食べます。- Tôi thức dậy, rửa mặt rồi ăn sáng.</p><h3><code>V1てから、V2</code></h3><p>• 宿題をしてから、テレビを見ます。- Sau khi làm bài, tôi xem tivi.</p><h3><code>N1 は N2 が A です</code></h3><p>• ミラーさんは背が高いです。- Anh Miller cao.</p><p>• この町は道が広いです。- Thành phố này có đường rộng.</p><h3>Nối tính từ và danh từ</h3><p>• <code>安くて、おいしいです</code>; <code>静かで、きれいです</code>; <code>先生で、日本人です</code>.</p><p>• Không dùng cách nối này khi hai ý tương phản; dùng <code>が</code>.</p></div>', 'GRAMMAR'),
(16, 4, 'Đọc hiểu', '兄は背が高くて、明るい人です。大学の先生で、英語を教えています。毎朝ジョギングをしてから、大学へ行きます。', '<div class="n5-lesson-content"><blockquote>兄は背が高くて、明るい人です。大学の先生で、英語を教えています。毎朝ジョギングをしてから、大学へ行きます。</blockquote><p>1. Người anh có đặc điểm gì? 2. Làm nghề gì? 3. Làm gì trước khi đến trường?</p></div>', 'LESSON'),
(16, 5, 'Nghe và hội thoại', 'A: 東京駅までどうやって行きますか。', '<div class="n5-lesson-content"><p>A: 東京駅までどうやって行きますか。</p><p>B: この電車に乗って、新宿で降りて、中央線に乗り換えてください。</p><p>Nhiệm vụ: ghi đúng trình tự di chuyển; giới thiệu một người bằng ba đặc điểm nối nhau.</p></div>', 'LISTENING'),
(16, 6, 'Đáp án', 'Đọc: 背が高くて明るい, 大学の先生, ジョギング.', '<div class="n5-lesson-content"><p>• Đọc: <code>背が高くて明るい</code>, <code>大学の先生</code>, <code>ジョギング</code>.</p><p>• Nối <code>静かです + 便利です</code> -&gt; <code>静かで、便利です。</code></p></div>', 'EXERCISE'),
(17, 1, 'Mục tiêu Can-do', 'Chia động từ sang thể phủ định ない.', '<div class="n5-lesson-content"><p>• Chia động từ sang thể phủ định <code>ない</code>.</p><p>• Nói yêu cầu không làm, nghĩa vụ phải làm và việc không cần làm.</p><p>• Nói hạn chót hoàn thành.</p></div>', 'LESSON'),
(17, 2, 'Từ vựng', '覚えます（おぼえます） ghi nhớ; 忘れます（わすれます） quên; なくします làm mất; 出します（だします） nộp; 払います（はらいます） trả tiền; 返します（かえします） trả lại; 脱ぎます（ぬぎます） cởi; 持って行きます mang đi; 心配します（しんぱいします） lo lắng; 残業（ざんぎょう） làm thêm giờ; 薬（くすり） thuốc; 保険証（ほけんしょう） thẻ bảo hiểm; までに trước hạn.', '<div class="n5-lesson-content"><p><code>覚えます（おぼえます）</code> ghi nhớ; <code>忘れます（わすれます）</code> quên; <code>なくします</code> làm mất; <code>出します（だします）</code> nộp; <code>払います（はらいます）</code> trả tiền; <code>返します（かえします）</code> trả lại; <code>脱ぎます（ぬぎます）</code> cởi; <code>持って行きます</code> mang đi; <code>心配します（しんぱいします）</code> lo lắng; <code>残業（ざんぎょう）</code> làm thêm giờ; <code>薬（くすり）</code> thuốc; <code>保険証（ほけんしょう）</code> thẻ bảo hiểm; <code>までに</code> trước hạn.</p></div>', 'VOCABULARY'),
(17, 3, 'Ngữ pháp', '書きます -> 書かない; 食べます -> 食べない; します -> しない; 来ます -> 来ない.', '<div class="n5-lesson-content"><h3>Thể <code>ない</code></h3><p>• <code>書きます -&gt; 書かない</code>; <code>食べます -&gt; 食べない</code>; <code>します -&gt; しない</code>; <code>来ます -&gt; 来ない</code>.</p><h3><code>Vないでください</code></h3><p>• ここに荷物を置かないでください。- Xin đừng để hành lý ở đây.</p><h3><code>Vなければなりません</code></h3><p>• 毎日、薬を飲まなければなりません。- Hằng ngày phải uống thuốc.</p><h3><code>Vなくてもいいです</code></h3><p>• 明日は来なくてもいいです。- Ngày mai không cần đến.</p><h3><code>N thời gian までに V</code></h3><p>• 金曜日までにレポートを出してください。- Hãy nộp báo cáo trước thứ Sáu.</p></div>', 'GRAMMAR'),
(17, 4, 'Đọc hiểu', '試験は来週です。学生は金曜日までに申込書を出さなければなりません。辞書を持って来てはいけません。でも、鉛筆は持って来なければなりません。', '<div class="n5-lesson-content"><blockquote>試験は来週です。学生は金曜日までに申込書を出さなければなりません。辞書を持って来てはいけません。でも、鉛筆は持って来なければなりません。</blockquote><p>1. Khi nào thi? 2. Hạn nộp đơn? 3. Thứ gì không được mang? 4. Thứ gì phải mang?</p></div>', 'LESSON'),
(17, 5, 'Nghe và hội thoại', 'A: 明日も七時に来なければなりませんか。', '<div class="n5-lesson-content"><p>A: 明日も七時に来なければなりませんか。</p><p>B: いいえ、明日は早く来なくてもいいです。でも、九時までに来てください。</p><p>Nhiệm vụ: ghi việc bắt buộc, không bắt buộc và hạn chót; lập ba nội quy lớp học.</p></div>', 'LISTENING'),
(17, 6, 'Đáp án', 'Đọc: 来週, 金曜日まで, 辞書, 鉛筆.', '<div class="n5-lesson-content"><p>• Đọc: <code>来週</code>, <code>金曜日まで</code>, <code>辞書</code>, <code>鉛筆</code>.</p><p>• <code>飲みます -&gt; 飲まない</code>; <code>起きます -&gt; 起きない</code>; <code>勉強します -&gt; 勉強しない</code>.</p></div>', 'EXERCISE'),
(18, 1, 'Mục tiêu Can-do', 'Chia và dùng thể từ điển.', '<div class="n5-lesson-content"><p>• Chia và dùng thể từ điển.</p><p>• Nói khả năng và sở thích.</p><p>• Nói một hành động xảy ra trước hành động khác.</p></div>', 'LESSON'),
(18, 2, 'Từ vựng', 'できます có thể; 洗います（あらいます） rửa; 弾きます（ひきます） chơi nhạc cụ; 歌います（うたいます） hát; 集めます（あつめます） sưu tầm; 捨てます（すてます） vứt; 運転します（うんてんします） lái xe; 予約します（よやくします） đặt trước; 趣味（しゅみ） sở thích; ピアノ piano; 釣り（つり） câu cá; 日記（にっき） nhật ký; 前に（まえに） trước khi.', '<div class="n5-lesson-content"><p><code>できます</code> có thể; <code>洗います（あらいます）</code> rửa; <code>弾きます（ひきます）</code> chơi nhạc cụ; <code>歌います（うたいます）</code> hát; <code>集めます（あつめます）</code> sưu tầm; <code>捨てます（すてます）</code> vứt; <code>運転します（うんてんします）</code> lái xe; <code>予約します（よやくします）</code> đặt trước; <code>趣味（しゅみ）</code> sở thích; <code>ピアノ</code> piano; <code>釣り（つり）</code> câu cá; <code>日記（にっき）</code> nhật ký; <code>前に（まえに）</code> trước khi.</p></div>', 'VOCABULARY'),
(18, 3, 'Ngữ pháp', '書きます -> 書く; 飲みます -> 飲む; 食べます -> 食べる; します -> する; 来ます -> 来る.', '<div class="n5-lesson-content"><h3>Thể từ điển</h3><p>• <code>書きます -&gt; 書く</code>; <code>飲みます -&gt; 飲む</code>; <code>食べます -&gt; 食べる</code>; <code>します -&gt; する</code>; <code>来ます -&gt; 来る</code>.</p><h3><code>N／Vること が できます</code></h3><p>• 私は車の運転ができます。- Tôi có thể lái xe.</p><p>• 日本語で歌うことができます。- Tôi có thể hát bằng tiếng Nhật.</p><h3><code>趣味は N／Vること です</code></h3><p>• 私の趣味は写真です。- Sở thích của tôi là nhiếp ảnh.</p><p>• 趣味は本を読むことです。- Sở thích là đọc sách.</p><h3><code>Nの／Vる 前に</code></h3><p>• 寝る前に歯を磨きます。- Tôi đánh răng trước khi ngủ.</p><p>• 食事の前に手を洗います。- Tôi rửa tay trước bữa ăn.</p></div>', 'GRAMMAR'),
(18, 4, 'Đọc hiểu', '私の趣味は旅行することです。日本語と英語を話すことができます。旅行の前にホテルを予約します。寝る前に次の日の予定を確認します。', '<div class="n5-lesson-content"><blockquote>私の趣味は旅行することです。日本語と英語を話すことができます。旅行の前にホテルを予約します。寝る前に次の日の予定を確認します。</blockquote><p>1. Sở thích là gì? 2. Có thể nói ngôn ngữ nào? 3. Làm gì trước chuyến đi và trước khi ngủ?</p></div>', 'LESSON'),
(18, 5, 'Nghe và hội thoại', 'A: 何か楽器ができますか。', '<div class="n5-lesson-content"><p>A: 何か楽器ができますか。</p><p>B: はい、ギターを弾くことができます。</p><p>A: いつ練習しますか。</p><p>B: 晩ご飯を食べる前に練習します。</p><p>Nhiệm vụ: ghi khả năng và thời điểm luyện tập; phỏng vấn bạn về sở thích.</p></div>', 'LISTENING'),
(18, 6, 'Đáp án', 'Đọc: 旅行, 日本語と英語, ホテルを予約する／予定を確認する.', '<div class="n5-lesson-content"><p>• Đọc: <code>旅行</code>, <code>日本語と英語</code>, <code>ホテルを予約する／予定を確認する</code>.</p><p>• “Tôi không thể bơi” -&gt; <code>泳ぐことができません。</code></p></div>', 'EXERCISE'),
(19, 1, 'Mục tiêu Can-do', 'Chia động từ sang thể た.', '<div class="n5-lesson-content"><p>• Chia động từ sang thể <code>た</code>.</p><p>• Kể trải nghiệm trong quá khứ.</p><p>• Liệt kê hoạt động và mô tả sự thay đổi trạng thái.</p></div>', 'LESSON'),
(19, 2, 'Từ vựng', '登ります（のぼります） leo; 泊まります（とまります） trọ; 掃除します（そうじします） dọn dẹp; 洗濯します（せんたくします） giặt; 練習します（れんしゅうします） luyện tập; なります trở nên; 眠い（ねむい） buồn ngủ; 強い（つよい） mạnh; 弱い（よわい） yếu; 調子（ちょうし） tình trạng; 一度（いちど） một lần; だんだん dần dần; ぜひ nhất định.', '<div class="n5-lesson-content"><p><code>登ります（のぼります）</code> leo; <code>泊まります（とまります）</code> trọ; <code>掃除します（そうじします）</code> dọn dẹp; <code>洗濯します（せんたくします）</code> giặt; <code>練習します（れんしゅうします）</code> luyện tập; <code>なります</code> trở nên; <code>眠い（ねむい）</code> buồn ngủ; <code>強い（つよい）</code> mạnh; <code>弱い（よわい）</code> yếu; <code>調子（ちょうし）</code> tình trạng; <code>一度（いちど）</code> một lần; <code>だんだん</code> dần dần; <code>ぜひ</code> nhất định.</p></div>', 'VOCABULARY'),
(19, 3, 'Ngữ pháp', 'Đổi từ thể て: 書いて -> 書いた; 飲んで -> 飲んだ; 食べて -> 食べた; して -> した.', '<div class="n5-lesson-content"><h3>Thể <code>た</code></h3><p>Đổi từ thể <code>て</code>: <code>書いて -&gt; 書いた</code>; <code>飲んで -&gt; 飲んだ</code>; <code>食べて -&gt; 食べた</code>; <code>して -&gt; した</code>.</p><h3><code>Vたことがあります</code></h3><p>• 富士山に登ったことがあります。- Tôi từng leo núi Phú Sĩ.</p><p>• 日本へ行ったことがありません。- Tôi chưa từng đến Nhật.</p><h3><code>Vたり、Vたりします</code></h3><p>• 日曜日は本を読んだり、音楽を聞いたりします。- Chủ nhật tôi đọc sách, nghe nhạc và làm những việc tương tự.</p><h3><code>A／N に なります</code></h3><p>• 寒くなりました。- Trời đã trở lạnh.</p><p>• 日本語が上手になりました。- Tiếng Nhật đã khá hơn.</p><p>• 来年、先生になります。- Năm sau tôi sẽ trở thành giáo viên.</p></div>', 'GRAMMAR'),
(19, 4, 'Đọc hiểu', '去年、日本へ行ったことがあります。大阪に泊まって、お城を見たり、日本料理を食べたりしました。毎日日本語を使いましたから、前より上手になりました。', '<div class="n5-lesson-content"><blockquote>去年、日本へ行ったことがあります。大阪に泊まって、お城を見たり、日本料理を食べたりしました。毎日日本語を使いましたから、前より上手になりました。</blockquote><p>1. Đã từng đi đâu? 2. Làm những hoạt động gì? 3. Điều gì đã tiến bộ?</p></div>', 'LESSON'),
(19, 5, 'Nghe và hội thoại', 'A: スキーをしたことがありますか。', '<div class="n5-lesson-content"><p>A: スキーをしたことがありますか。</p><p>B: はい、一度あります。北海道で滑りました。</p><p>A: どうでしたか。</p><p>B: 難しかったですが、だんだん上手になりました。</p><p>Nhiệm vụ: ghi trải nghiệm, nơi và cảm nhận; kể hai việc từng hoặc chưa từng làm.</p></div>', 'LISTENING'),
(19, 6, 'Đáp án', 'Đọc: 日本, お城を見る／日本料理を食べる, 日本語.', '<div class="n5-lesson-content"><p>• Đọc: <code>日本</code>, <code>お城を見る／日本料理を食べる</code>, <code>日本語</code>.</p><p>• Thể <code>た</code>: <code>行きます -&gt; 行った</code>; <code>読みます -&gt; 読んだ</code>; <code>食べます -&gt; 食べた</code>.</p></div>', 'EXERCISE'),
(20, 1, 'Mục tiêu Can-do', 'Phân biệt thể lịch sự và thể thông thường.', '<div class="n5-lesson-content"><p>• Phân biệt thể lịch sự và thể thông thường.</p><p>• Chuyển động từ, tính từ và danh từ sang thể thông thường.</p><p>• Trò chuyện tự nhiên với bạn bè hoặc người thân.</p></div>', 'LESSON'),
(20, 2, 'Từ vựng', '要ります（いります） cần; 調べます（しらべます） tra cứu; 直します（なおします） sửa; 修理します（しゅうりします） sửa chữa; 僕（ぼく） tôi, nam giới; 君（きみ） cậu; 言葉（ことば） từ/ngôn từ; 物価（ぶっか） giá cả; 着物（きもの） kimono; ビザ thị thực; こっち／そっち／あっち／どっち cách nói thân mật; うん ừ; ううん không.', '<div class="n5-lesson-content"><p><code>要ります（いります）</code> cần; <code>調べます（しらべます）</code> tra cứu; <code>直します（なおします）</code> sửa; <code>修理します（しゅうりします）</code> sửa chữa; <code>僕（ぼく）</code> tôi, nam giới; <code>君（きみ）</code> cậu; <code>言葉（ことば）</code> từ/ngôn từ; <code>物価（ぶっか）</code> giá cả; <code>着物（きもの）</code> kimono; <code>ビザ</code> thị thực; <code>こっち／そっち／あっち／どっち</code> cách nói thân mật; <code>うん</code> ừ; <code>ううん</code> không.</p></div>', 'VOCABULARY'),
(20, 3, 'Ngữ pháp', '高いです -> 高い; 高くないです -> 高くない; 高かったです -> 高かった.', '<div class="n5-lesson-content"><h3>Động từ thể thông thường</h3><p>Ý | Lịch sự | Thông thường</p><p>Hiện tại khẳng định | 書きます | 書く</p><p>Hiện tại phủ định | 書きません | 書かない</p><p>Quá khứ khẳng định | 書きました | 書いた</p><p>Quá khứ phủ định | 書きませんでした | 書かなかった</p><h3>Tính từ và danh từ</h3><p>• <code>高いです -&gt; 高い</code>; <code>高くないです -&gt; 高くない</code>; <code>高かったです -&gt; 高かった</code>.</p><p>• <code>静かです -&gt; 静かだ</code>; <code>静かじゃありません -&gt; 静かじゃない</code>.</p><p>• <code>学生です -&gt; 学生だ</code>; trong câu hỏi thân mật thường bỏ <code>だ</code>: <code>学生？</code>.</p><h3>Hội thoại thân mật</h3><p>• 明日ひま？- Mai rảnh không?</p><p>• うん、ひま。映画を見る？- Ừ, rảnh. Xem phim không?</p><p>• ごめん、見ない。- Xin lỗi, không xem.</p><p>Chỉ dùng thể thông thường với người thân hoặc khi quan hệ cho phép.</p></div>', 'GRAMMAR'),
(20, 4, 'Đọc hiểu', 'A: そのかばん、いいね。どこで買った？', '<div class="n5-lesson-content"><blockquote>A: そのかばん、いいね。どこで買った？</blockquote><blockquote>B: 駅の近くの店で買った。あまり高くなかったよ。</blockquote><blockquote>A: そう。私も新しいかばんが要る。</blockquote><p>1. Mua cặp ở đâu? 2. Cặp có đắt không? 3. Người A cần gì?</p></div>', 'LESSON'),
(20, 5, 'Nghe và thực hành', 'A: 日曜日、何をした？', '<div class="n5-lesson-content"><p>A: 日曜日、何をした？</p><p>B: 友達とサッカーをした。それから、ラーメンを食べた。</p><p>A: 楽しかった？</p><p>B: うん、とても楽しかった。</p><p>Nhiệm vụ: chuyển đoạn trên sang thể lịch sự, rồi kể cuối tuần với bạn bằng thể thông thường.</p></div>', 'LISTENING'),
(20, 6, 'Đáp án', 'Đọc: 駅の近くの店, 高くなかった, 新しいかばん.', '<div class="n5-lesson-content"><p>• Đọc: <code>駅の近くの店</code>, <code>高くなかった</code>, <code>新しいかばん</code>.</p><p>• Lịch sự: <code>何をしましたか／サッカーをしました／食べました／楽しかったですか</code>.</p></div>', 'EXERCISE'),
(21, 1, 'Mục tiêu Can-do', 'Trình bày suy nghĩ hoặc dự đoán.', '<div class="n5-lesson-content"><p>• Trình bày suy nghĩ hoặc dự đoán.</p><p>• Trích dẫn lời nói trực tiếp và gián tiếp.</p><p>• Xác nhận điều hai bên cùng biết và đưa ra gợi ý nhẹ.</p></div>', 'LESSON'),
(21, 2, 'Từ vựng', '思います（おもいます） nghĩ; 言います（いいます） nói; 勝ちます（かちます） thắng; 負けます（まけます） thua; 役に立ちます（やくにたちます） hữu ích; 動きます（うごきます） chuyển động; やめます nghỉ/dừng; 気をつけます chú ý; 留学します（りゅうがくします） du học; 意見（いけん） ý kiến; ニュース tin tức; 交通（こうつう） giao thông; たぶん có lẽ.', '<div class="n5-lesson-content"><p><code>思います（おもいます）</code> nghĩ; <code>言います（いいます）</code> nói; <code>勝ちます（かちます）</code> thắng; <code>負けます（まけます）</code> thua; <code>役に立ちます（やくにたちます）</code> hữu ích; <code>動きます（うごきます）</code> chuyển động; <code>やめます</code> nghỉ/dừng; <code>気をつけます</code> chú ý; <code>留学します（りゅうがくします）</code> du học; <code>意見（いけん）</code> ý kiến; <code>ニュース</code> tin tức; <code>交通（こうつう）</code> giao thông; <code>たぶん</code> có lẽ.</p></div>', 'VOCABULARY'),
(21, 3, 'Ngữ pháp', '明日は雨が降ると思います。- Tôi nghĩ ngày mai trời mưa.', '<div class="n5-lesson-content"><h3><code>Thể thông thường + と思います</code></h3><p>• 明日は雨が降ると思います。- Tôi nghĩ ngày mai trời mưa.</p><p>• 日本語はおもしろいと思います。- Tôi nghĩ tiếng Nhật thú vị.</p><p>• 田中さんは来ないと思います。- Tôi nghĩ anh Tanaka không đến.</p><h3><code>Câu + と言います</code></h3><p>• 先生は「宿題を出してください」と言いました。- Giáo viên nói: “Hãy nộp bài”.</p><p>• 先生は明日テストがあると言いました。- Giáo viên nói ngày mai có bài kiểm tra.</p><h3><code>～でしょう？</code> và <code>Nでも</code></h3><p>• この店は安いでしょう？- Quán này rẻ phải không?</p><p>• コーヒーでも飲みませんか。- Uống cà phê hay gì đó nhé?</p></div>', 'GRAMMAR'),
(21, 4, 'Đọc hiểu', '私はベトナムの生活は楽しいと思います。食べ物がおいしくて、人が親切です。友達は「交通は少し大変だ」と言いました。でも、これからもっと便利になると思います。', '<div class="n5-lesson-content"><blockquote>私はベトナムの生活は楽しいと思います。食べ物がおいしくて、人が親切です。友達は「交通は少し大変だ」と言いました。でも、これからもっと便利になると思います。</blockquote><p>1. Người viết nghĩ gì? 2. Người bạn nói gì về giao thông? 3. Tương lai sẽ thế nào?</p></div>', 'LESSON'),
(21, 5, 'Nghe và hội thoại', 'A: 次の試合はどちらが勝つと思う？', '<div class="n5-lesson-content"><p>A: 次の試合はどちらが勝つと思う？</p><p>B: 日本が勝つと思う。でも、難しい試合になるでしょう。</p><p>A: そうだね。ジュースでも飲みながら見よう。</p><p>Nhiệm vụ: ghi dự đoán và lời xác nhận; thảo luận về một thành phố hoặc trận đấu.</p></div>', 'LISTENING'),
(21, 6, 'Đáp án', 'Đọc: 生活は楽しい, 交通は少し大変, もっと便利になる.', '<div class="n5-lesson-content"><p>• Đọc: <code>生活は楽しい</code>, <code>交通は少し大変</code>, <code>もっと便利になる</code>.</p><p>• “Tôi nghĩ cô ấy là giáo viên” -&gt; <code>彼女は先生だと思います。</code></p></div>', 'EXERCISE'),
(22, 1, 'Mục tiêu Can-do', 'Dùng mệnh đề để bổ nghĩa cho danh từ.', '<div class="n5-lesson-content"><p>• Dùng mệnh đề để bổ nghĩa cho danh từ.</p><p>• Nói rõ người, vật hoặc nơi chốn đang được nhắc đến.</p><p>• Dùng cụm danh từ dài làm chủ đề hoặc tân ngữ.</p></div>', 'LESSON'),
(22, 2, 'Từ vựng', '着ます（きます） mặc áo; はきます mặc quần/đi giày; かぶります đội; かけます đeo kính; 生まれます（うまれます） sinh ra; コート áo khoác; スーツ vest; 眼鏡（めがね） kính; 帽子（ぼうし） mũ; 家賃（やちん） tiền thuê nhà; 台所（だいどころ） bếp; 和室（わしつ） phòng kiểu Nhật; こちら người/vị này.', '<div class="n5-lesson-content"><p><code>着ます（きます）</code> mặc áo; <code>はきます</code> mặc quần/đi giày; <code>かぶります</code> đội; <code>かけます</code> đeo kính; <code>生まれます（うまれます）</code> sinh ra; <code>コート</code> áo khoác; <code>スーツ</code> vest; <code>眼鏡（めがね）</code> kính; <code>帽子（ぼうし）</code> mũ; <code>家賃（やちん）</code> tiền thuê nhà; <code>台所（だいどころ）</code> bếp; <code>和室（わしつ）</code> phòng kiểu Nhật; <code>こちら</code> người/vị này.</p></div>', 'VOCABULARY'),
(22, 3, 'Ngữ pháp', 'Trong mệnh đề bổ nghĩa không dùng は cho chủ ngữ; thường dùng が.', '<div class="n5-lesson-content"><h3><code>Mệnh đề thể thông thường + N</code></h3><p>Trong mệnh đề bổ nghĩa không dùng <code>は</code> cho chủ ngữ; thường dùng <code>が</code>.</p><p>• 昨日買った本 - quyển sách đã mua hôm qua.</p><p>• 母が作ったケーキ - chiếc bánh mẹ làm.</p><p>• 眼鏡をかけている人 - người đang đeo kính.</p><h3>Cụm danh từ trong câu</h3><p>• これは京都で撮った写真です。- Đây là ảnh chụp ở Kyoto.</p><p>• 私が昨日見た映画はおもしろかったです。- Bộ phim tôi xem hôm qua rất thú vị.</p><p>• 私は庭がある家が欲しいです。- Tôi muốn căn nhà có vườn.</p></div>', 'GRAMMAR'),
(22, 4, 'Đọc hiểu', '私が住んでいる家は駅の近くにあります。去年建てた新しい家です。父が作った小さい庭があります。庭で母が育てている花はとてもきれいです。', '<div class="n5-lesson-content"><blockquote>私が住んでいる家は駅の近くにあります。去年建てた新しい家です。父が作った小さい庭があります。庭で母が育てている花はとてもきれいです。</blockquote><p>1. Nhà ở đâu? 2. Nhà được xây khi nào? 3. Ai làm vườn? 4. Hoa nào đẹp?</p></div>', 'LESSON'),
(22, 5, 'Nghe và hội thoại', 'A: あそこで本を読んでいる人はだれですか。', '<div class="n5-lesson-content"><p>A: あそこで本を読んでいる人はだれですか。</p><p>B: 山田先生です。先生が書いた本を読んでいます。</p><p>A: どの本ですか。</p><p>B: 青い表紙の本です。</p><p>Nhiệm vụ: xác định người và quyển sách; miêu tả ba người trong lớp bằng mệnh đề bổ nghĩa.</p></div>', 'LISTENING'),
(22, 6, 'Đáp án', 'Đọc: 駅の近く, 去年, 父, 母が育てている花.', '<div class="n5-lesson-content"><p>• Đọc: <code>駅の近く</code>, <code>去年</code>, <code>父</code>, <code>母が育てている花</code>.</p><p>• Ghép “Tôi đã mua máy tính hôm qua” thành cụm danh từ -&gt; <code>私が昨日買ったパソコン</code>.</p></div>', 'EXERCISE'),
(23, 1, 'Mục tiêu Can-do', 'Nói thời điểm một hành động hoặc trạng thái xảy ra.', '<div class="n5-lesson-content"><p>• Nói thời điểm một hành động hoặc trạng thái xảy ra.</p><p>• Diễn tả kết quả tự nhiên khi thực hiện một thao tác.</p><p>• Hỏi và chỉ đường bằng chuỗi chỉ dẫn.</p></div>', 'LESSON'),
(23, 2, 'Từ vựng', '聞きます（ききます） hỏi/nghe; 回します（まわします） vặn; 引きます（ひきます） kéo; 変えます（かえます） đổi; 触ります（さわります） chạm; 出ます（でます） đi ra; 歩きます（あるきます） đi bộ; 渡ります（わたります） băng qua; 曲がります（まがります） rẽ; 交差点（こうさてん） giao lộ; 信号（しんごう） đèn giao thông; 角（かど） góc; 橋（はし） cầu; 道（みち） đường.', '<div class="n5-lesson-content"><p><code>聞きます（ききます）</code> hỏi/nghe; <code>回します（まわします）</code> vặn; <code>引きます（ひきます）</code> kéo; <code>変えます（かえます）</code> đổi; <code>触ります（さわります）</code> chạm; <code>出ます（でます）</code> đi ra; <code>歩きます（あるきます）</code> đi bộ; <code>渡ります（わたります）</code> băng qua; <code>曲がります（まがります）</code> rẽ; <code>交差点（こうさてん）</code> giao lộ; <code>信号（しんごう）</code> đèn giao thông; <code>角（かど）</code> góc; <code>橋（はし）</code> cầu; <code>道（みち）</code> đường.</p></div>', 'VOCABULARY'),
(23, 3, 'Ngữ pháp', '日本へ行くとき、パスポートが要ります。- Khi đi Nhật cần hộ chiếu.', '<div class="n5-lesson-content"><h3><code>Vる／Vない／Vた とき</code></h3><p>• 日本へ行くとき、パスポートが要ります。- Khi đi Nhật cần hộ chiếu.</p><p>• 分からないとき、先生に聞きます。- Khi không hiểu, tôi hỏi giáo viên.</p><p>• 家へ帰ったとき、電話してください。- Khi đã về nhà, hãy gọi cho tôi.</p><h3><code>Aい／Aな／N のとき</code></h3><p>• 忙しいとき、朝ご飯を食べません。- Khi bận tôi không ăn sáng.</p><p>• 子どものとき、よく川で泳ぎました。- Hồi nhỏ tôi thường bơi ở sông.</p><h3><code>Vると、～</code></h3><p>Dùng cho kết quả tự nhiên, thao tác máy móc hoặc đường đi; không dùng cho mệnh lệnh hay ý chí của người nói.</p><p>• このボタンを押すと、ドアが開きます。- Nhấn nút này thì cửa mở.</p><p>• 右へ曲がると、駅があります。- Rẽ phải thì có nhà ga.</p></div>', 'GRAMMAR'),
(23, 4, 'Đọc hiểu', '駅を出ると、大きい道があります。その道をまっすぐ歩いて、二つ目の信号を左へ曲がってください。右に銀行があります。学校は銀行の隣です。', '<div class="n5-lesson-content"><blockquote>駅を出ると、大きい道があります。その道をまっすぐ歩いて、二つ目の信号を左へ曲がってください。右に銀行があります。学校は銀行の隣です。</blockquote><p>1. Ra khỏi ga thấy gì? 2. Rẽ ở đâu? 3. Trường nằm ở đâu?</p></div>', 'LESSON'),
(23, 5, 'Nghe và hội thoại', 'A: ATMの使い方が分からないんですが…。', '<div class="n5-lesson-content"><p>A: ATMの使い方が分からないんですが…。</p><p>B: このカードを入れると、画面が変わります。それから暗証番号を押してください。</p><p>Nhiệm vụ: sắp xếp thao tác theo thứ tự; dùng bản đồ để chỉ đường cho bạn.</p></div>', 'LISTENING'),
(23, 6, 'Đáp án', 'Đọc: 大きい道, 二つ目の信号を左, 銀行の隣.', '<div class="n5-lesson-content"><p>• Đọc: <code>大きい道</code>, <code>二つ目の信号を左</code>, <code>銀行の隣</code>.</p><p>• “Khi rảnh tôi đọc sách” -&gt; <code>暇なとき、本を読みます。</code></p></div>', 'EXERCISE'),
(24, 1, 'Mục tiêu Can-do', 'Phân biệt cho và nhận đồ vật từ góc nhìn người nói.', '<div class="n5-lesson-content"><p>• Phân biệt cho và nhận đồ vật từ góc nhìn người nói.</p><p>• Nói ai làm một hành động có lợi cho ai.</p><p>• Thể hiện sự biết ơn phù hợp.</p></div>', 'LESSON'),
(24, 2, 'Từ vựng', 'くれます cho tôi/người phía tôi; 連れて行きます（つれていきます） dẫn đi; 連れて来ます（つれてきます） dẫn đến; 送ります（おくります） tiễn/gửi; 紹介します（しょうかいします） giới thiệu; 案内します（あんないします） hướng dẫn; 説明します（せつめいします） giải thích; おじいさん ông; おばあさん bà; 準備（じゅんび） chuẩn bị; 全部（ぜんぶ） toàn bộ; 自分で（じぶんで） tự mình.', '<div class="n5-lesson-content"><p><code>くれます</code> cho tôi/người phía tôi; <code>連れて行きます（つれていきます）</code> dẫn đi; <code>連れて来ます（つれてきます）</code> dẫn đến; <code>送ります（おくります）</code> tiễn/gửi; <code>紹介します（しょうかいします）</code> giới thiệu; <code>案内します（あんないします）</code> hướng dẫn; <code>説明します（せつめいします）</code> giải thích; <code>おじいさん</code> ông; <code>おばあさん</code> bà; <code>準備（じゅんび）</code> chuẩn bị; <code>全部（ぜんぶ）</code> toàn bộ; <code>自分で（じぶんで）</code> tự mình.</p></div>', 'VOCABULARY'),
(24, 3, 'Ngữ pháp', '友達は私に本をくれました。- Bạn đã tặng tôi sách.', '<div class="n5-lesson-content"><h3><code>A は 私に N を くれます</code></h3><p>• 友達は私に本をくれました。- Bạn đã tặng tôi sách.</p><h3><code>A は B に Vてあげます</code></h3><p>• 私は妹に日本語を教えてあげました。- Tôi dạy tiếng Nhật cho em gái.</p><p>Tránh dùng trực tiếp với người trên vì có thể tạo cảm giác khoe ơn.</p><h3><code>A は B に Vてもらいます</code></h3><p>• 私は先生に作文を直してもらいました。- Tôi được giáo viên sửa bài văn cho.</p><h3><code>A が 私に Vてくれます</code></h3><p>• 友達が駅まで送ってくれました。- Bạn đã tiễn tôi đến ga.</p></div>', 'GRAMMAR'),
(24, 4, 'Đọc hiểu', '引っ越しの日、友達が手伝いに来てくれました。田中さんは荷物を運んでくれました。私は山田さんに車を貸してもらいました。終わってから、みんなに晩ご飯を作ってあげました。', '<div class="n5-lesson-content"><blockquote>引っ越しの日、友達が手伝いに来てくれました。田中さんは荷物を運んでくれました。私は山田さんに車を貸してもらいました。終わってから、みんなに晩ご飯を作ってあげました。</blockquote><p>1. Ai đến giúp? 2. Tanaka làm gì? 3. Người kể được Yamada giúp gì? 4. Người kể làm gì để cảm ơn?</p></div>', 'LESSON'),
(24, 5, 'Nghe và hội thoại', 'A: その写真、きれいですね。だれが撮りましたか。', '<div class="n5-lesson-content"><p>A: その写真、きれいですね。だれが撮りましたか。</p><p>B: 友達が撮ってくれました。京都も案内してくれました。</p><p>A: いい友達ですね。</p><p>Nhiệm vụ: ghi hai việc người bạn đã làm; kể một lần bạn được ai đó giúp.</p></div>', 'LISTENING'),
(24, 6, 'Đáp án', 'Đọc: 友達, 荷物を運ぶ, 車を貸してもらう, 晩ご飯を作る.', '<div class="n5-lesson-content"><p>• Đọc: <code>友達</code>, <code>荷物を運ぶ</code>, <code>車を貸してもらう</code>, <code>晩ご飯を作る</code>.</p><p>• “Mẹ làm bánh cho tôi” -&gt; <code>母が私にケーキを作ってくれました。</code></p></div>', 'EXERCISE'),
(25, 1, 'Mục tiêu Can-do', 'Đặt giả định bằng ～たら.', '<div class="n5-lesson-content"><p>• Đặt giả định bằng <code>～たら</code>.</p><p>• Dùng <code>～たら</code> để nói việc xảy ra sau khi một mốc hoàn tất.</p><p>• Diễn đạt kết quả trái với điều thường được mong đợi bằng <code>～ても</code>.</p></div>', 'LESSON'),
(25, 2, 'Từ vựng', '考えます（かんがえます） suy nghĩ; 着きます（つきます） đến nơi; 足ります（たります） đủ; 田舎（いなか） quê; チャンス cơ hội; 億（おく） một trăm triệu; もし nếu; いくら dù bao nhiêu; 転勤（てんきん） chuyển công tác; 頑張ります（がんばります） cố gắng; 年を取ります lớn tuổi; 意味（いみ） ý nghĩa.', '<div class="n5-lesson-content"><p><code>考えます（かんがえます）</code> suy nghĩ; <code>着きます（つきます）</code> đến nơi; <code>足ります（たります）</code> đủ; <code>田舎（いなか）</code> quê; <code>チャンス</code> cơ hội; <code>億（おく）</code> một trăm triệu; <code>もし</code> nếu; <code>いくら</code> dù bao nhiêu; <code>転勤（てんきん）</code> chuyển công tác; <code>頑張ります（がんばります）</code> cố gắng; <code>年を取ります</code> lớn tuổi; <code>意味（いみ）</code> ý nghĩa.</p></div>', 'VOCABULARY'),
(25, 3, 'Ngữ pháp', 'Tạo bằng thể quá khứ thông thường + ら.', '<div class="n5-lesson-content"><h3><code>～たら、～</code> - điều kiện</h3><p>Tạo bằng thể quá khứ thông thường + <code>ら</code>.</p><p>• 時間があったら、旅行したいです。- Nếu có thời gian, tôi muốn du lịch.</p><p>• 雨だったら、出かけません。- Nếu trời mưa, tôi không ra ngoài.</p><p>• 安かったら、このパソコンを買います。- Nếu rẻ, tôi sẽ mua máy tính này.</p><h3><code>～たら、～</code> - sau khi</h3><p>• 駅に着いたら、電話してください。- Khi đến ga, hãy gọi cho tôi.</p><p>• 仕事が終わったら、食事に行きましょう。- Làm xong việc thì đi ăn nhé.</p><h3><code>～ても、～</code></h3><p>• 雨が降っても、試合をします。- Dù mưa vẫn thi đấu.</p><p>• 高くても、必要なら買います。- Dù đắt, nếu cần tôi vẫn mua.</p><p>• 暇でも、今日は出かけません。- Dù rảnh, hôm nay tôi không đi chơi.</p></div>', 'GRAMMAR'),
(25, 4, 'Đọc hiểu', 'もし一億ドンあったら、日本へ留学したいです。日本へ行ったら、いろいろな町を旅行します。日本語が難しくても、毎日勉強します。困ったときは先生に相談します。', '<div class="n5-lesson-content"><blockquote>もし一億ドンあったら、日本へ留学したいです。日本へ行ったら、いろいろな町を旅行します。日本語が難しくても、毎日勉強します。困ったときは先生に相談します。</blockquote><p>1. Nếu có tiền sẽ làm gì? 2. Sau khi đến Nhật sẽ làm gì? 3. Dù tiếng Nhật khó thì sao?</p></div>', 'LESSON'),
(25, 5, 'Nghe và hội thoại', 'A: 夏休みになったら、何をしたいですか。', '<div class="n5-lesson-content"><p>A: 夏休みになったら、何をしたいですか。</p><p>B: 海へ行きたいです。雨が降っても、ホテルでゆっくりできます。</p><p>A: いいですね。ホテルを予約したら、教えてください。</p><p>Nhiệm vụ: ghi kế hoạch, tình huống bất lợi và hành động sau khi đặt phòng; trình bày kế hoạch của mình với cả <code>たら</code> và <code>ても</code>.</p></div>', 'LISTENING'),
(25, 6, 'Tổng ôn và đáp án', '駅に（着いたら／着いても）、電話してください。 -> 着いたら.', '<div class="n5-lesson-content"><p>1. <code>駅に（着いたら／着いても）、電話してください。</code> -&gt; <code>着いたら</code>.</p><p>2. <code>雨が（降ったら／降っても）、サッカーをします。</code> -&gt; <code>降っても</code>.</p><p>3. “Nếu rảnh, hãy đến chơi” -&gt; <code>暇だったら、遊びに来てください。</code></p><p>4. “Dù suy nghĩ cũng không hiểu” -&gt; <code>考えても、分かりません。</code></p><p>Tự đánh giá cuối trình độ: học viên viết 8-10 câu về một kế hoạch giả định, sau đó trình bày trong 60 giây và trả lời hai câu hỏi của bạn học.</p></div>', 'EXERCISE');
